window.TITANS_1000_QUOTES = [{"id": "01_altman", "ep": "01", "name": "Сем Альтман", "latin": "Sam Altman", "avatar": "assets/avatars/sam_altman.jpg", "quotes_100": [{"num": 1, "cat": "Експонента", "text": "Людський мозок еволюційно лінійний; здатність мислити експонентами — це рідкісна ментальна модель, що відокремлює архітекторів майбутнього."}, {"num": 2, "cat": "Ірраціональна віра", "text": "«Якщо ви не вірите у власну здатність змінювати правила гри, ніхто за вас у це не повірить. Експонента винагороджує лише сміливих»."}, {"num": 3, "cat": "Перший Macintosh", "text": "«У 1993 році цей Macintosh LC II розмив лінію між моїм внутрішнім світом і всесвітом. Я зрозумів: світ не зафіксований назавжди. Його можна перепрограмувати»."}, {"num": 4, "cat": "Довгостроковий горизонт", "text": "«Більшість людей переоцінюють те, що можуть зробити за рік, і недооцінюють те, що здатні створити за десять років»."}, {"num": 5, "cat": "Справжній ризик", "text": "«Справжній ризик — це грати надто обережно, коли світ навколо вас рухається експоненціально»."}, {"num": 6, "cat": "Школа Y Combinator", "text": "Пол Грем навчив мене головного: робіть те, що потрібно користувачам, і ігноруйте статус-кво академічних авторитетів."}, {"num": 7, "cat": "Психологічне тертя", "text": "Більшість людей здаються не тому, що їхня ідея хибна. Вони здаються, тому що не здатні витримати психологічне тертя щоденних відмов."}, {"num": 8, "cat": "Не бійтеся амбіцій", "text": "Легше залучити ресурси під проект, який змінює цивілізацію, ніж під черговий дрібний сервіс доставки їжі."}, {"num": 9, "cat": "Самостійне судження", "text": "Якщо ви рухаєтеся туди, де всі вже погоджуються з вами — ви вже запізнилися. Шукайте правду в точках найбільшого опору консенсусу."}, {"num": 10, "cat": "Швидкість як стратегія", "text": "Висока швидкість ітерацій б'є будь-яке повільне планування. Той, хто помиляється вдесятеро швидше, виграє ринок."}, {"num": 11, "cat": "Знищення застарілого", "text": "«Ніколи не оптимізуйте те, що має бути повністю знищено та перебудовано з нуля»."}, {"num": 12, "cat": "Ціна комфорту", "text": "Комфорт — це головний вбивця великих амбіцій. Найкращі речі створюються в стані контрольованого дискомфорту."}, {"num": 13, "cat": "Мережеві ефекти", "text": "Справжня монополія в технологіях будується на накопиченні користувацької цінності та мережевих ефектах експоненти."}, {"num": 14, "cat": "Відбір талантів", "text": "Один надзвичайний інженер вартий п'ятдесяти посередніх. Будуйте команди з людей, які мають іскру фанатизму."}, {"num": 15, "cat": "Культура ультиматумів", "text": "Коли ви впевнені у фундаментальному законі природи — не йдіть на компроміси заради спокою ради директорів."}, {"num": 16, "cat": "Зосередженість на істині", "text": "Світ щодня переконуватиме вас у вашій пересічності. Ваше завдання — ігнорувати шум і фокусуватися на сигналі."}, {"num": 17, "cat": "Право на сміливість", "text": "У 16 років публічний камінг-аут перед християнською школою навчив мене: якщо ви боїтеся бути собою, ви ніколи не зможете очолити революцію."}, {"num": 18, "cat": "Уроки Стенфорду", "text": "Я кинув Стенфорд не тому, що навчання було поганим, а тому, що реальний світ вимагав негайної дії."}, {"num": 19, "cat": "Досвід Loopt", "text": "Loopt продав за $43.4 млн. Це був скромний фінансовий результат, але це була безцінна школа інженерії волі."}, {"num": 20, "cat": "Сміливість ставити все", "text": "Тільки ті, хто готові ризикнути всім своїм капіталом і репутацією, здатні відкрити новий технологічний уклад."}, {"num": 21, "cat": "Етика переможця", "text": "Справжня перемога — це створення інфраструктури, яка піднімає рівень життя всього людства."}, {"num": 22, "cat": "Відсікання токсичності", "text": "Якщо людина в команді не вірить у спільну місію на 100% — прощайтеся з нею негайно."}, {"num": 23, "cat": "Рівень рішучості", "text": "Рішучість (resoluteness) — це якість номер один для лідера експоненціальної компанії."}, {"num": 24, "cat": "Ментальна стійкість", "text": "Критики забудуть свої слова через місяць. Ваші результати залишаться в коді назавжди."}, {"num": 25, "cat": "Концентрація зусиль", "text": "Справжній успіх — це результат звуження фокусу до однієї точки найвищого тиску."}, {"num": 26, "cat": "Народження OpenAI", "text": "У грудні 2015 року ми заснували OpenAI як некомерційну противагу монополізації ШІ однією корпорацією."}, {"num": 27, "cat": "Обчислювальний імператив", "text": "«Ми не зможемо врятувати світ, якщо у нас банально не вистачить обчислювальних потужностей перевірити власні рівняння»."}, {"num": 28, "cat": "Трансформація capped-profit", "text": "Ідеалізм без капіталу безпорадний. Щоб побудувати суперкомп'ютери для AGI, ми мали залучити мільярди доларів."}, {"num": 29, "cat": "Союз із Microsoft", "text": "Партнерство з Сатьєю Наделою дало нам необхідні хмарні кластери Azure, які перетворили дослідження на реальність."}, {"num": 30, "cat": "Магія GPT-3", "text": "Коли GPT-3 почав писати код і розмірковувати, скептики зрозуміли: закон масштабування працює безвідмовно."}, {"num": 31, "cat": "ChatGPT як момент біфуркації", "text": "30 листопада 2022 року світ змінився назавжди. Інтерфейс чату зробив штучний інтелект відчутним для кожного."}, {"num": 32, "cat": "Суть AGI", "text": "AGI — це не одна програма. Це система, здатна самостійно генерувати нові наукові знання швидше за все людство."}, {"num": 33, "cat": "Зміна економіки", "text": "Вартість інтелекту впаде майже до нуля. Головними обмежувачами залишаться енергія та кремній."}, {"num": 34, "cat": "Демократизація інструментів", "text": "ШІ має бути персональним суперінтелектуальним помічником кожного студента, лікаря та інженера на Землі."}, {"num": 35, "cat": "Відкритість проти закритості", "text": "Безпека AGI вимагає поступового релізу (iterative deployment), щоб суспільство встигало адаптуватися до змін."}, {"num": 36, "cat": "Проблема узгодження", "text": "Вирівнювання суперінтелекту з людськими цінностями — це найважливіша математична та філософська проблема століття."}, {"num": 37, "cat": "Закон масштабування обчислень", "text": "Кожне десятикратне збільшення обчислень відкриває нові якісні властивості моделей."}, {"num": 38, "cat": "Смерть вузьких моделей", "text": "Ера спеціалізованих нейромереж добігла кінця; мультимодальні фундаментальні моделі поглинають усі окремі завдання."}, {"num": 39, "cat": "Співпраця з Ілоном Маском", "text": "Ілон допоміг запустити OpenAI, але коли він зажадав тотального контролю, ми обрали автономію місії."}, {"num": 40, "cat": "Капіталомісткість майбутнього", "text": "Для навчання AGI наступного покоління знадобляться дата-центри вартістю у сотні мільярдів доларів."}, {"num": 41, "cat": "Еволюція інтерфейсів", "text": "Текстовий промпт — це лише перший крок; майбутнє за мультимодальною присутністю і голосовим симбіозом."}, {"num": 42, "cat": "Науковий прорив як мета", "text": "Якщо AGI не здатний винайти термоядерний синтез і вилікувати рак — ми збудували недостатньо потужну систему."}, {"num": 43, "cat": "Суверенітет розуму", "text": "Людство не повинно залежати від рішень однієї компанії; саме тому ми будуємо відкриті API для всього світу."}, {"num": 44, "cat": "Швидкість адаптації соціуму", "text": "Суспільство дивовижно швидко звикає до чудес: те, що вчора здавалося магією, сьогодні стає буденним інструментом."}, {"num": 45, "cat": "Приборкання галюцинацій", "text": "Галюцинації — це зворотний бік творчої уяви моделі; системне міркування (o1) навчає ШІ перевіряти факти."}, {"num": 46, "cat": "Проблема енергетичного дефіциту", "text": "Наступна фаза масштабування ШІ вимагатиме нової атомної енергетики та сонячних кластерів."}, {"num": 47, "cat": "Інвестиції в Helion Energy", "text": "Я інвестував у ядерний термояд, тому що без чистих гігаватів ми не зможемо живити кластери майбутнього."}, {"num": 48, "cat": "Інвестиції в Retro Biosciences", "text": "ШІ продовжить продуктивне життя людини на десятки років — саме тому біотех є невіддільним від нашої місії."}, {"num": 49, "cat": "Модель о1 та мислення", "text": "Перехід від генерації слів до ланцюжків міркувань (Chain of Thought) — це народження справжнього логічного агента."}, {"num": 50, "cat": "Горизонт автономних агентів", "text": "Через два роки агенти виконуватимуть складні багатокрокові інженерні завдання без прямого контролю людини."}, {"num": 51, "cat": "Удар 17 листопада", "text": "Рада директорів звільнила мене у п'ятницю через Google Meet. Це був класичний корпоративний саботаж під маскою безпеки."}, {"num": 52, "cat": "Мовчання і концентрація", "text": "У перші години після звільнення головне було не піддатися гніву, а оцінити конфігурацію сил на дошці."}, {"num": 53, "cat": "Ультиматум команди", "text": "«Коли 730 із 770 співробітників підписали лист із вимогою мого повернення, я зрозумів: компанію тримають не статути, а спільна віра»."}, {"num": 54, "cat": "Роль Сатьї Наделли", "text": "Microsoft проявила абсолютну вірність партнерству, запропонувавши створити нову лабораторію для всієї команди OpenAI."}, {"num": 55, "cat": "Психологія тиску", "text": "Найболючіші удари завжди завдають ті, з ким ви ділили хліб у підвалі стартапу. Пробачте їх і рухайтеся далі."}, {"num": 56, "cat": "Перемога відкритості", "text": "Таємні змови в закритих кімнатах більше не працюють у цифрову епоху: публічність стала нашою головною зброєю."}, {"num": 57, "cat": "Тріумф повернення", "text": "22 листопада я повернувся на посаду CEO з новою радою директорів — Ларрі Саммерсом та Бретом Тейлором."}, {"num": 58, "cat": "Очищення культури", "text": "Криза виявила приховані тріщини і дозволила перебудувати управління компанією на рівень світових корпорацій."}, {"num": 59, "cat": "Урок стійкості", "text": "Лідер пізнається не в момент запуску успішного продукту, а в момент, коли весь світ вважає його кар'єру завершеною."}, {"num": 60, "cat": "Людський фактор", "text": "Жоден алгоритм не замінить щирої довіри між людьми, які щодня будують майбутнє пліч-о-пліч."}, {"num": 61, "cat": "Відповідальність перед інвесторами", "text": "Ми довели, що здатні захистити капітал та інтереси партнерів навіть у стані максимального шторму."}, {"num": 62, "cat": "Ціна публічності", "text": "Коли ви керуєте компанією в центрі світової уваги, будь-який ваш крок розглядається під мікроскопом історії."}, {"num": 63, "cat": "Фокус на продукті", "text": "Під час кризи ми не зупинили сервери ані на секунду; безперервність сервісу для 100 млн користувачів була законом."}, {"num": 64, "cat": "Провал палацового перевороту", "text": "Ідеологи, які відірвані від реального інженерного процесу, завжди програють практикам, які будують продукт."}, {"num": 65, "cat": "Нова рада директорів", "text": "Ми залучили важковаговиків світової економіки та безпеки, щоб OpenAI мала фундамент для наступного стрибка."}, {"num": 66, "cat": "Прощення опонентів", "text": "Я не тримаю зла на членів колишньої ради; вони діяли з власних переконань, хоча їхні методи були згубними."}, {"num": 67, "cat": "Збереження темпу", "text": "Головний ризик кризи полягав у втраті ініціативи перед Google та Anthropic; ми компенсували це подвійною швидкістю."}, {"num": 68, "cat": "Культура міцного ядра", "text": "Після листопада 2023 року наша команда стала монолітом, який неможливо розколоти зовнішнім тиском."}, {"num": 69, "cat": "Смирення після тріумфу", "text": "Повернення не було приводом для пихи; це було нагадуванням про те, наскільки тендітною є будь-яка організація."}, {"num": 70, "cat": "Інституційна пам'ять", "text": "Ми записали кожен крок кризи, щоб створити протоколи антикризового реагування на майбутні виклики."}, {"num": 71, "cat": "Стійкість до критики преси", "text": "Заголовки медіа змінюються кожні 48 годин; єдине, що має значення — це реліз коду і стабільність моделей."}, {"num": 72, "cat": "Захист дослідників", "text": "Моє головне завдання як CEO — бути кремнієвим щитом між геніальними вченими та хаосом зовнішньої політики."}, {"num": 73, "cat": "Довіра користувачів", "text": "Користувачі підтримали нас, тому що ChatGPT став для них незамінним щоденним помічником у праці."}, {"num": 74, "cat": "Перезапуск місії", "text": "Листопад показав: наша мета надто велика, щоб дозволити дрібним внутрішнім амбіціям зупинити прогрес."}, {"num": 75, "cat": "Погляд за горизонт", "text": "Коли шторм вщух, ми повернулися до головного питання: як забезпечити енергетичний базис для появи AGI."}, {"num": 76, "cat": "Проект Stargate", "text": "«Створення Stargate — кластера вартістю $100 мільярдів — це не примха, це фізична вимога наступного покоління моделей»."}, {"num": 77, "cat": "Енергія як валюта", "text": "«Головна валюта майбутнього — це обчислення та гігавати чистої енергії. Той, хто контролює кремній і вольти, формує архітектуру мислення»."}, {"num": 78, "cat": "Закон Мура проти закону енергії", "text": "Транзистори більше не стають дешевше автоматично; тепер ми повинні будувати цілі електростанції поруч із дата-центрами."}, {"num": 79, "cat": "Термоядерний горизонт", "text": "Справжній екологічний ШІ стане можливим лише тоді, коли запрацюють перші комерційні реактори синтезу."}, {"num": 80, "cat": "Чіпи власної розробки", "text": "Залежність від одного постачальника GPU — це вузьке горло для цивілізації; ми повинні диверсифікувати кремнієву базу."}, {"num": 81, "cat": "ШІ та науковий метод", "text": "AGI прискорить науковий пошук у тисячі разів: від синтезу надпровідників до квантової хімії."}, {"num": 82, "cat": "Пост-дефіцитна економіка", "text": "Коли інтелект і праця стануть дешевими, людство вперше в історії позбудеться проблеми матеріального дефіциту."}, {"num": 83, "cat": "Універсальний базовий дохід", "text": "ШІ згенерує колосальне багатство; Worldcoin та цифрова ідентичність — це спроба підготувати механізми перерозподілу."}, {"num": 84, "cat": "Нова роль людини", "text": "Людина не зникне з ринку праці, але перейде на рівень формулювання сенсів, етики та естетичних векторів."}, {"num": 85, "cat": "Глобальне регулювання", "text": "Ми підтримуємо створення міжнародного агентства на зразок МАГАТЕ для моніторингу найпотужніших навчальних кластерів."}, {"num": 86, "cat": "Геополітичні перегони", "text": "Демократичний світ зобов'язаний виграти перегони за AGI, інакше авторитарні моделі нав'яжуть цифрову цензуру планеті."}, {"num": 87, "cat": "ШІ у медицині", "text": "Кожна людина отримає рівень медичної консультації найкращого консиліуму лікарів прямо у своєму смартфоні."}, {"num": 88, "cat": "Освіта майбутнього", "text": "Індивідуальний ШІ-тьютор адаптуватиме подачу матеріалу під нейропластичність кожної дитини."}, {"num": 89, "cat": "Масштабування вирівнювання", "text": "Ми будемо використовувати слабкі моделі для перевірки і вирівнювання надпотужних систем наступного покоління."}, {"num": 90, "cat": "Сингулярність без містики", "text": "Сингулярність — це не кінець світу, це просто точка, де швидкість технологічних інновацій перевищує швидкість адаптації старих інститутів."}, {"num": 91, "cat": "Відповідальність перед дітьми", "text": "Світ, який ми залишимо нашим дітям, буде наділений магією творчості: будь-яка уява зможе миттєво стати матеріальним кодом."}, {"num": 92, "cat": "Смирення будівничого", "text": "Ми не боги, ми просто інженери, які підняли камінь і побачили під ним закон математичного розуму."}, {"num": 93, "cat": "Свобода мислення", "text": "ШІ не повинен бути цензурованим моралізатором; він має допомагати людині досліджувати правду у всій її складності."}, {"num": 94, "cat": "Інфраструктурний патріотизм", "text": "Будівництво дата-центрів у США та країнах-партнерах — це питання збереження технологічного лідерства вільного світу."}, {"num": 95, "cat": "Еволюція розуму", "text": "Інтелект у всесвіті — надзвичайно рідкісна річ; допомогти йому спалахнути в кремнії — наш священний обов'язок."}, {"num": 96, "cat": "Право на помилку", "text": "Ми робитимемо помилки, релізитимемо недосконалі версії, виправлятимемо баги. Але ми ніколи не зупинимо рух уперед."}, {"num": 97, "cat": "Справжня ціна компромісу", "text": "Якщо ви зупините дослідження в ім'я фальшивого спокою, технологію створять ті, хто взагалі не дбає про права людини."}, {"num": 98, "cat": "Код експоненти", "text": "Експонента не прощає зволікань: один день відставання на старті перетворюється на прірву в світлові роки у фіналі."}, {"num": 99, "cat": "Діалог поколінь", "text": "Ми стоїмо на плечах Буля, Тюрінга, фон Неймана і Хінтона; наш обов'язок — передати цей вогонь далі."}, {"num": 100, "cat": "Фінальний маніфест", "text": "«Майбутнє не трапляється саме по собі. Його виковують люди, які не побоялися повірити в експоненту і поставили на кін усе»."}]}, {"id": "02_huang", "ep": "02", "name": "Дженсен Хуанг", "latin": "Jensen Huang", "avatar": "assets/avatars/jensen_huang.jpg", "quotes_100": [{"num": 1, "cat": "Філософія страждання", "text": "«Я бажаю вам достатньо болю і страждань. Тому що саме страждання формують характер, а характер формує долю величних компаній»."}, {"num": 2, "cat": "Школа Denny's", "text": "«У 15 років я працював посудомийником у закусочній Denny's у Портленді. Я чистив туалети і мив посуд краще за всіх у світі. Це навчило мене гідності ремесла»."}, {"num": 3, "cat": "Баптистський інтернат", "text": "Oneida Baptist Institute у Кентуккі загартував мене: коли ти 9-річний іммігрант без знання мови чистиш вбиральні, ти вчишся виживати за будь-яких умов."}, {"num": 4, "cat": "Постійний страх краху", "text": "«Ми завжди були за 30 днів до банкрутства. Цей щоденний страх — найкраще паливо для інновацій та захисту від закостеніння»."}, {"num": 5, "cat": "Витривалість (Grit)", "text": "Інтелект переоцінений; витривалість (grit) — це головний предиктор довгострокового тріумфу в інженерії та бізнесі."}, {"num": 6, "cat": "Ставлення до праці", "text": "«Байдуже, чи миєте ви посуд у нічній забігайлівці, чи проектуєте чіп на 200 мільярдів транзисторів — робіть це так, ніби від кожної дії залежить всесвіт»."}, {"num": 7, "cat": "Стійкість до невдач", "text": "Помилки — це не привід для сорому. Це просто безкоштовні уроки фізики та ринку."}, {"num": 8, "cat": "Культура прямоти", "text": "В NVIDIA немає кабінетної бюрократії. Я можу зайти в будь-яку лабораторію і поговорити з молодшим інженером напряму."}, {"num": 9, "cat": "Пласка структура", "text": "У мене 50 прямих підлеглих. Що менше рівнів менеджменту між лідером та інженером, то чистіший сигнал."}, {"num": 10, "cat": "Біжи, а не йди", "text": "«Біжи, не йди. Або ти біжиш за їжею, або біжиш, щоб самому не стати чиєюсь їжею»."}, {"num": 11, "cat": "Настільний теніс", "text": "Третє місце на юніорському чемпіонаті США з пінг-понгу навчило мене мікросекундній реакції та нещадному фокусу на м'ячі."}, {"num": 12, "cat": "Шкіряна куртка як форма", "text": "Я ношу однаковий чорний одяг і шкіряну куртку, щоб не витрачати ані секунди ранкової енергії на вибір гардеробу."}, {"num": 13, "cat": "Смирення лідера", "text": "Генеральний директор не повинен бути вельможею. Він повинен бути головним розв'язувачем проблем у компанії."}, {"num": 14, "cat": "Здатність терпіти біль", "text": "Успіх вимірюється не тим, скільки грошей ви заробили, а тим, скільки агонії ви змогли витримати на шляху до мети."}, {"num": 15, "cat": "Відмова від консенсусу", "text": "Якщо аналітики Уолл-стріт хвалять вашу стратегію, ви робите щось очевидне і банальне."}, {"num": 16, "cat": "Гартування кризами", "text": "Криза 1995 року, коли чіп NV1 провалився, навчила мене дивитися смерті компанії в очі без паніки."}, {"num": 17, "cat": "Рятівний дзвінок Sega", "text": "Я чесно зізнався генеральному директору Sega у провалі архітектури NV1, і він дав нам $5 млн авансу на RIVA 128 за нашу чесність."}, {"num": 18, "cat": "Уроки Denny's 1993", "text": "NVIDIA народилася за столиком Denny's за чашкою безкоштовної кави. Справжні революції починаються в скромних місцях."}, {"num": 19, "cat": "Чесність перед клієнтом", "text": "Ніколи не продавайте клієнту те, у що самі не вірите всім серцем."}, {"num": 20, "cat": "Сила оптимізму", "text": "Песимісти мають рацію у деталях, але оптимісти будують нові галактики."}, {"num": 21, "cat": "Ціна компромісу", "text": "Краще зазнати чистої інженерної поразки, ніж випустити посередній компромісний продукт."}, {"num": 22, "cat": "Щоденний перезапуск", "text": "Щоранку я прокидаюся з думкою, що компанію треба рятувати знову з чистого аркуша."}, {"num": 23, "cat": "Свобода від его", "text": "Визнати, що ти витратив три роки на хибну архітектуру і спалити її — це найвища форма мужності."}, {"num": 24, "cat": "Довіра до команди", "text": "Якщо ви наймаєте найкращих у світі людей, не вказуйте їм кожен крок — дайте їм свободу творити дива."}, {"num": 25, "cat": "Інженерний стоїцизм", "text": "Закони термодинаміки неможливо підкупити маркетингом. Будуйте на фундаментальній фізиці."}, {"num": 26, "cat": "Винахід GPU", "text": "У 1999 році ми винайшли GeForce 256 — перший у світі графічний процесор, який звільнив комп'ютер від рамок 2D."}, {"num": 27, "cat": "Паралельна парадигма", "text": "Центральний процесор (CPU) — це швидкий літак, а графічний процесор (GPU) — це армія з мільйона мурах, здатних зрушити гори."}, {"num": 28, "cat": "Фізика 3D графіки", "text": "Тривимірна графіка вимагала мільярдів обчислень матриць одночасно; це був ідеальний тренажер для майбутнього ШІ."}, {"num": 29, "cat": "Тріумф RIVA 128", "text": "У 1997 році чіп RIVA 128 врятував компанію від банкрутства і встановив стандарт швидкості для всієї індустрії ПК."}, {"num": 30, "cat": "Смерть 3dfx", "text": "Купівля активів 3dfx Voodoo довела: перемагає не культовий бренд, а безжальна інженерна дисципліна випуску чіпів кожні 6 місяців."}, {"num": 31, "cat": "Ставка на DirectX", "text": "Ми тісно співпрацювали з Microsoft, щоб зробити апаратне 3D-прискорення серцем кожної операційної системи Windows."}, {"num": 32, "cat": "Термодинамічний бар'єр", "text": "Закон Деннарда помер 15 років тому: центральні процесори вперлися у перегрів, і єдиним виходом став паралелізм."}, {"num": 33, "cat": "Шейдерна революція", "text": "Програмовані шейдери в GeForce 3 перетворили GPU з фіксованого конвеєра на універсальний математичний інструмент."}, {"num": 34, "cat": "Кремнієвий закон", "text": "Чим більше транзисторів ви можете ефективно змусити працювати паралельно, тим ближче ви до імітації нейронів мозку."}, {"num": 35, "cat": "Інтеграція пам'яті", "text": "Обчислення без пропускної здатності пам'яті марні; HBM пам'ять стала такою ж важливою, як і самі ядра."}, {"num": 36, "cat": "Швидкість як конкурентна перевага", "text": "Ми скоротили цикл проектування суперчіпів з чотирьох років до вісімнадцяти місяців."}, {"num": 37, "cat": "Фізика світла (Ray Tracing)", "text": "У 2018 році з запуском RTX ми поставили на апаратне трасування променів у реальному часі, коли всі казали, що це неможливо ще 10 років."}, {"num": 38, "cat": "Нейрорендерінг DLSS", "text": "Традиційний рендеринг пікселів мертвий; тепер ми генеруємо картинку за допомогою нейромереж у реальному часі."}, {"num": 39, "cat": "Співпраця з TSMC", "text": "Морріс Чанг став моїм наставником і братом по зброї. Без літографії TSMC революція NVIDIA була б неможливою."}, {"num": 40, "cat": "Упаковка чіпів CoWoS", "text": "Передова упаковка кремнію (Chip-on-Wafer-on-Substrate) стала новим полем битви за продуктивність."}, {"num": 41, "cat": "Оптимізація інженерного стеку", "text": "Ми проектуємо не просто чіп — ми проектуємо транзистори, підкладку, оптоволокно, сервери та софт як єдине ціле."}, {"num": 42, "cat": "Подолання фізичних меж", "text": "Коли довжина хвилі світла стала більшою за елементи чіпа, ми застосували обчислювальну літографію на GPU."}, {"num": 43, "cat": "Кремній як мистецтво", "text": "Погляньте на кристал Blackwell під мікроскопом: 208 мільярдів транзисторів рухаються в ідеальному танці зі швидкістю світла."}, {"num": 44, "cat": "Справжня ціна кремнію", "text": "Кожна пластина коштує десятки тисяч доларів, і одна порошинка може знищити чіп; тут немає місця недбалості."}, {"num": 45, "cat": "Перегони мікронів", "text": "Перехід від мікронів до нанометрів вимагав мільярдних ставок на обладнання ASML Extreme Ultraviolet."}, {"num": 46, "cat": "Енергоефективність архітектури", "text": "Продуктивність на ват — це єдина метрика, яка має значення для суперкомп'ютерів наступного століття."}, {"num": 47, "cat": "Провал NV1 як благословення", "text": "Якби наш перший чіп був успішним, ми б ніколи не створили GPU. Невдача змусила нас переосмислити все."}, {"num": 48, "cat": "Партнерство з геймерами", "text": "Геймери всього світу фінансували наші дослідження протягом 20 років, перш ніж з'явився штучний інтелект."}, {"num": 49, "cat": "Гідність інженера", "text": "Інженер — це людина, яка змушує пісок (кремній) думати і розмовляти."}, {"num": 50, "cat": "Вірність парадигмі", "text": "Ми трималися за ідею прискорених обчислень тридцять років, коли весь ринок вважав це нішевою забавкою."}, {"num": 51, "cat": "Запуск CUDA 2006", "text": "«У 2006 році ми інтегрували CUDA в кожен наш чіп безкоштовно. Це коштувало нам мільярдів доларів і обвалило акції, але створило сучасний ШІ»."}, {"num": 52, "cat": "Zero-Billion-Dollar Markets", "text": "«Ніколи не йдіть туди, де вже штовхаються конкуренти. Шукайте ринки, які оцінюються у нуль доларів, і створюйте нові галузі з нуля»."}, {"num": 53, "cat": "Уолл-стріт проти CUDA", "text": "Аналітики благали мене вилучити блоки CUDA і знизити собівартість. Якби я їх послухав, ШІ-революція затрималася б на 15 років."}, {"num": 54, "cat": "DGX-1 для OpenAI", "text": "У 2016 році я особисто привіз у Сан-Франциско перший суперкомп'ютер DGX-1 і підписав його для Ілона Маска та Сема Альтмана."}, {"num": 55, "cat": "Апаратний симбіоз з AlexNet", "text": "Коли Хінтон і Суцкевер запустили AlexNet на двох геймерських картах GTX 580, ми зрозуміли: настав наш зоряний час."}, {"num": 56, "cat": "Швидкість як екосистема", "text": "CUDA — це не просто мова програмування. Це мільйони бібліотек (cuDNN, TensorRT), які неможливо скопіювати за один день."}, {"num": 57, "cat": "Монополія користі", "text": "Конкуренти намагаються скопіювати наше залізо, але вони не розуміють: справжня цінність полягає в екосистемі програмного забезпечення."}, {"num": 58, "cat": "Математика матричного множення", "text": "Штучний інтелект у своїй основі — це гігантське множення матриць. Ми оптимізували Tensor Cores саме під цю операцію."}, {"num": 59, "cat": "Інвестиції у збиткові роки", "text": "Десять років поспіль інвестори карали наші акції за інвестиції в наукові обчислення. Ми вистояли завдяки вірі у фізику."}, {"num": 60, "cat": "Перетворення GPU на AI суперкомп'ютер", "text": "Один сервер більше не є одиницею обчислень; одиницею став дата-центр з 100 000 з'єднаних чіпів."}, {"num": 61, "cat": "Культура відкритості для вчених", "text": "Ми роздавали плати університетам безкоштовно, щоб виростити покоління дослідників, які вміють писати код для GPU."}, {"num": 62, "cat": "Перехід від графіки до науки", "text": "Моделювання згортання білків, астрофізика, прогноз клімату — все це перейшло на CUDA задовго до появи ChatGPT."}, {"num": 63, "cat": "Захисний рів екосистеми", "text": "Справжній рів (moat) — це не патенти. Це чотири мільйони розробників, які звикли думати в термінах нашої платформи."}, {"num": 64, "cat": "Сміливість створювати попит", "text": "Ми створили обчислювальну потужність для генеративного ШІ ще до того, як світ зрозумів, що йому потрібен генеративний ШІ."}, {"num": 65, "cat": "Сила стандартизації", "text": "Той самий код, написаний для ноутбука розробника, працює на кластері з десяти тисяч GPU в дата-центрі."}, {"num": 66, "cat": "Створення платформи Omniverse", "text": "Omniverse — це цифровий двійник реальності для навчання роботів і тестування автономних фабрик."}, {"num": 67, "cat": "Смерть CPU у навчанні ШІ", "text": "Використовувати CPU для навчання сучасних LLM — це те саме, що намагатися викопати тунель чайною ложкою."}, {"num": 68, "cat": "Трансформація компанії", "text": "Ми перестали бути компанією чіпів і стали компанією інфраструктури обчислювальних платформ."}, {"num": 69, "cat": "Мережевий комутатор Quantum InfiniBand", "text": "Купівля Mellanox за $6.9 млрд була геніальним кроком: передача даних між GPU стала швидшою за шини материнської плати."}, {"num": 70, "cat": "Ціна терпіння", "text": "Терпіння в інженерії — це здатність щодня копати колодязь, навіть коли перші краплі води з'являться через десять років."}, {"num": 71, "cat": "Закон масштабування інфраструктури", "text": "Подвоєння кількості чіпів у кластері повинно давати лінійне прискорення навчання без втрат на синхронізацію."}, {"num": 72, "cat": "Довіра наукової спільноти", "text": "Вчені обирають NVIDIA, тому що наш код не підводить у критичний момент багатомісячного тренування моделей."}, {"num": 73, "cat": "Сміливість великих ставок", "text": "Ми поставили все майбутнє компанії на CUDA у 2006 році. Це був найбільший ва-банк в історії кремнієвої долини."}, {"num": 74, "cat": "Магія паралелізму", "text": "Коли тисячі ядер одночасно оновлюють ваги нейромережі, ви чуєте гул народження нової цифрової свідомості."}, {"num": 75, "cat": "Служіння науковому прогресу", "text": "NVIDIA існує для того, щоб розв'язувати задачі, які звичайні комп'ютери не здатні вирішити в принципі."}, {"num": 76, "cat": "Закон Хуанга", "text": "«Закон Мура помер. Закон Хуанга доводить: синергія чіпів, софту, мереж та охолодження збільшує продуктивність у 1000 разів за 8 років»."}, {"num": 77, "cat": "ШІ як промислова революція", "text": "«Штучний інтелект — це не програмне забезпечення. Це нова промислова епоха, де дата-центри перетворюють енергію на токени інтелекту»."}, {"num": 78, "cat": "ШІ-фабрики майбутнього", "text": "У 19 столітті фабрики виробляли текстиль і сталь завдяки паровим двигунам. Сьогодні ШІ-фабрики виробляють знання."}, {"num": 79, "cat": "Суверенний ШІ", "text": "«Кожна суверенна нація зобов'язана володіти власним ШІ, який береже її мову, культуру, історію та національні дані»."}, {"num": 80, "cat": "Смерть мов програмування", "text": "«Комп'ютер тепер розуміє людську мову. Найкращою мовою програмування у світі стала англійська, українська чи китайська»."}, {"num": 81, "cat": "Демократизація кодингу", "text": "Тепер кожен фермер, лікар чи вчитель є програмістом, тому що він може пояснити завдання штучному інтелекту словами."}, {"num": 82, "cat": "Чіп Blackwell B200", "text": "Blackwell — це не просто чіп; це двигун нової промислової революції, що виконує 20 квадрильйонів операцій на секунду."}, {"num": 83, "cat": "Рідкісне охолодження", "text": "Ми більше не можемо охолоджувати дата-центри повітрям; рідке охолодження стало обов'язковим інженерним стандартом."}, {"num": 84, "cat": "Енергетична ефективність токенів", "text": "Наша мета — зменшити споживання енергії на один згенерований токен у тисячі разів."}, {"num": 85, "cat": "Автономні роботи (Physical AI)", "text": "Наступна велика хвиля ШІ — це фізичний інтелект: гуманоїдні роботи, автономні трактори та автоматизовані заводи."}, {"num": 86, "cat": "Платформа Isaac для роботів", "text": "Роботи повинні спочатку прожити мільйони годин у віртуальному симуляторі Omniverse, перш ніж вийти на реальні вулиці."}, {"num": 87, "cat": "ШІ для проектування чіпів", "text": "Ми використовуємо моделі ШІ для розведення доріжок нових чіпів NVIDIA; людина вже не здатна вручну оптимізувати 200 млрд транзисторів."}, {"num": 88, "cat": "Капіталізація у $3 трильйони", "text": "Ринкова капіталізація — це просто оцінка довіри інвесторів. Головне — продовжувати працювати так, ніби ми за 30 днів до краху."}, {"num": 89, "cat": "Перегони інфраструктури", "text": "Той, хто першим збудує кластери на 1 000 000 GPU, отримає вирішальну технологічну перевагу в XXI столітті."}, {"num": 90, "cat": "Економіка знань", "text": "Генерація токенів стане найбільшим бізнесом на планеті, більшим за нафту, автомобілебудування та авіацію."}, {"num": 91, "cat": "Відповідальність перед планетою", "text": "Зменшення енергетичного сліду обчислень — це наш священний обов'язок перед майбутніми поколіннями."}, {"num": 92, "cat": "Партнерство з автогігантами", "text": "Автомобіль стає комп'ютером на колесах; DRIVE Thor керуватиме безпілотними машинами наступного десятиліття."}, {"num": 93, "cat": "Зміна геополітики", "text": "Обчислювальні потужності стали новим геополітичним ресурсом, еквівалентним ядерному арсеналу чи запасам нафти."}, {"num": 94, "cat": "Постійне переосмислення", "text": "Якщо ми перестанемо винаходити себе заново щороку, індустрія розчавить нас за лічені місяці."}, {"num": 95, "cat": "Любов до своєї справи", "text": "Я люблю приходити на роботу щоранку. Немає нічого більш захопливого, ніж бачити, як неможливе стає реальністю."}, {"num": 96, "cat": "Філософія лідерства", "text": "Лідер повинен бачити майбутнє так чітко, щоб його віра розганяла страх у серцях його команди."}, {"num": 97, "cat": "Спадщина NVIDIA", "text": "Ми побудували інструмент, який дозволить людству розгадати таємниці Всесвіту і вилікувати всі хвороби."}, {"num": 98, "cat": "Повага до конкурентів", "text": "Ми поважаємо конкурентів, але ми біжимо втричі швидше, тому що пам'ятаємо запах мильної води в Denny's."}, {"num": 99, "cat": "Мудрість майстра", "text": "Справжня велич — це не призи й оплески, це здатність спокійно продовжувати роботу після найгучніших перемог."}, {"num": 100, "cat": "Фінальне кредо", "text": "«Не бійтеся болю, шукайте найважчі завдання і пам'ятайте: характер виковується лише у вогні випробувань»."}]}, {"id": "03_hassabis", "ep": "03", "name": "Деміс Гассабіс", "latin": "Demis Hassabis", "avatar": "assets/avatars/demis_hassabis.jpg", "quotes_100": [{"num": 1, "cat": "Шахове мислення", "text": "У 4 роки я вперше сів за шахову дошку; шахи навчили мене бачити дерево рішень і прораховувати наслідки на багато кроків уперед."}, {"num": 2, "cat": "Юний майстер", "text": "У 13 років я став майстром з рейтингом 2300. Перші призові кошти я витратив на комп'ютер ZX Spectrum, щоб вчитися програмувати правила гри."}, {"num": 3, "cat": "Theme Park у 17 років", "text": "У 17 років я був провідним програмістом гри Theme Park у Пітера Моліньє. Моделювання симуляцій навчило мене архітектурі віртуальних світів."}, {"num": 4, "cat": "Кембриджський гарт", "text": "Кембридж дав мені фундаментальну базу комп'ютерних наук: від алгоритмів сортування до складності обчислень."}, {"num": 5, "cat": "Поліматія як метод", "text": "Вузькі спеціалісти стають заручниками шаблонів. Великі прориви стаються на перетині комп'ютерних наук і нейробіології мозку."}, {"num": 6, "cat": "Elixir Studios", "text": "Заснування власної ігрової студії показало мені, наскільки складно керувати творчими колективами без чіткого алгоритмічного бачення."}, {"num": 7, "cat": "Дерево рішень життя", "text": "Припиніть реагувати на світ імпульсивно. Перед кожним важливим вибором візьміть паузу і розгляньте альтернативні гілки реальності."}, {"num": 8, "cat": "Геймдев як полігон для AGI", "text": "Відеоігри — це ідеальне середовище для навчання штучного інтелекту: безпечне, нескінченно масштабоване і з чіткими правилами перемоги."}, {"num": 9, "cat": "Краса правил", "text": "Світ підпорядкований математичним правилам; якщо ви розумієте базову фізику системи, ви здатні передбачити її еволюцію."}, {"num": 10, "cat": "Концентрація шахіста", "text": "Здатність годинами сидіти в повній тиші й утримувати в пам'яті десятки варіантів партій — це найкраща підготовка для дослідника AGI."}, {"num": 11, "cat": "Роль уяви", "text": "Шахіст бачить не просто позицію фігур на дошці — він уявляє силові поля та лінії напруги, яких фізично не існує."}, {"num": 12, "cat": "Здатність ризикувати фігурами", "text": "Жертва ферзя заради позиційної переваги навчила мене: іноді потрібно віддати великі ресурси сьогодні заради перемоги завтра."}, {"num": 13, "cat": "Школа самотності", "text": "Ігри навчили мене покладатися виключно на власний розрахунок у вирішальні моменти поєдинку."}, {"num": 14, "cat": "Код як живий організм", "text": "Коли ви пишете штучний інтелект для відеогри, ви відчуваєте себе деміургом, який вдихає іскру руху в пікселі."}, {"num": 15, "cat": "Гнучкість мислення", "text": "Якщо суперник робить несподіваний хід — не панікуйте. Перебудуйте свою стратегію і знайдіть слабкість у його зухвалості."}, {"num": 16, "cat": "Синтез логіки та інтуїції", "text": "Шахи — це не просто сухий розрахунок; це гармонія інтуїтивної оцінки позиції та залізної математики тактики."}, {"num": 17, "cat": "Повага до традиції", "text": "Тисячолітня історія шахів і ґо доводить, що людський розум здатен створювати шедеври неймовірної складності."}, {"num": 18, "cat": "Подолання людських обмежень", "text": "Я завжди мріяв створити гравця, який буде позбавлений втоми, страху і психологічних збоїв."}, {"num": 19, "cat": "Навчання через поразки", "text": "Кожна програна партія — це скарбниця знань. Перемоги тішать его, але поразки навчають мудрості."}, {"num": 20, "cat": "Ментальна дисципліна", "text": "Якщо ви втрачаєте контроль над емоціями біля дошки — ви вже програли. Спокій — це найпотужніша зброя."}, {"num": 21, "cat": "Стратегічне терпіння", "text": "Деякі позиції вимагають двадцяти ходів маневрування, перш ніж відкриється простір для вирішального удару."}, {"num": 22, "cat": "Естетика інтелекту", "text": "Справжня краса в науці виглядає так само, як красива комбінація на шахівниці: несподівано, гармонійно і безжально точно."}, {"num": 23, "cat": "Дитинство без гаджетів", "text": "Я виріс у родині без телевізора, де розмови про музику та філософію були щоденною нормою."}, {"num": 24, "cat": "Тяга до універсальності", "text": "Мене ніколи не цікавили програми, які вміють грати лише в одну гру; я прагнув створити універсальний алгоритм навчання."}, {"num": 25, "cat": "Вибір місії", "text": "У 30 років я зрозумів: моє життя надто коротке, щоб витрачати його на розваги. Я повинен розгадати таємницю інтелекту."}, {"num": 26, "cat": "PhD з нейробіології", "text": "Я пішов захищати дисертацію в UCL, щоб вивчити, як біологічний мозок створює уяву та консолідує спогади."}, {"num": 27, "cat": "Таємниця гіпокампа", "text": "Наші дослідження в Nature показали: гіпокамп відповідає не лише за спогади про минуле, але й за моделювання майбутнього."}, {"num": 28, "cat": "Заснування DeepMind 2010", "text": "Ми створили DeepMind у Лондоні з однією місією: розв'язати інтелект і за його допомогою вирішити всі інші проблеми науки."}, {"num": 29, "cat": "Інвестиція Пітера Тіля та Маска", "text": "Тіль і Маск повірили в нашу місію на ранньому етапі, коли ідея створення AGI вважалася науковою фантастикою."}, {"num": 30, "cat": "DQN: Atari Breakout", "text": "У 2013 році наш агент самостійно відкрив тунелювання в грі Breakout, вивчаючи лише пікселі екрану та рахунок."}, {"num": 31, "cat": "Купівля Google у 2014", "text": "Продаж DeepMind корпорації Google за £400 млн дав нам обчислювальні ресурси, про які європейські лабораторії могли лише мріяти."}, {"num": 32, "cat": "Етична рада", "text": "Однією з головних умов угоди з Google було створення незалежного етичного комітету для контролю за нашими дослідженнями."}, {"num": 33, "cat": "Симбіоз RL та Deep Learning", "text": "Поєднання глибоких нейромереж з навчанням з підкріпленням (Deep RL) стало ядром усіх наших проривів."}, {"num": 34, "cat": "Дофаміновий механізм у коді", "text": "Ми математично змоделювали помилку передбачення винагороди (TD-learning), що працює аналогічно дофаміну в мозку."}, {"num": 35, "cat": "Консолідація досвіду (Replay)", "text": "Агент повинен перегравати в пам'яті минулі епізоди у стані спокою, щоб закріпити успішні стратегії."}, {"num": 36, "cat": "Боротьба з катастрофічним забуванням", "text": "Як і мозок, нейромережа повинна захищати старі корисні синапси, коли засвоює нові навички."}, {"num": 37, "cat": "Пошук по дереву Монте-Карло (MCTS)", "text": "Поєднання нейромережевої інтуїції з MCTS дозволило AlphaGo оцінювати квадрильйони варіантів ходів."}, {"num": 38, "cat": "Лондон як наукова столиця", "text": "Ми відмовилися переїжджати в Кремнієву долину; DeepMind залишився в Лондоні поруч із провідними університетами Європи."}, {"num": 39, "cat": "Культура Bell Labs 21 століття", "text": "Ми створили атмосферу, де фундаментальна академічна наука поєднується з інженерною міццю світового техногіганта."}, {"num": 40, "cat": "Фокус на фундаментальних законах", "text": "Ми не розробляли рекламні алгоритми; кожен інженер DeepMind знав, що працює над загальним інтелектом."}, {"num": 41, "cat": "Принцип першопринципів", "text": "Завжди ставте запитання: що є фізичним обмеженням системи? Все інше — це просто питання часу та оптимізації."}, {"num": 42, "cat": "Ціна фокусу", "text": "Ми відхилили десятки комерційних проектів, щоб не розмивати увагу команди на дрібні заробітки."}, {"num": 43, "cat": "Співпраця з Google Brain", "text": "Об'єднання DeepMind та Google Brain у єдину структуру Google DeepMind у 2023 році консолідувало найкращі уми людства."}, {"num": 44, "cat": "Міжнародний склад лабораторії", "text": "У DeepMind працюють вчені з понад 60 країн світу: від фізиків-теоретиків до молекулярних біологів."}, {"num": 45, "cat": "Нейробіологічний компас", "text": "Коли алгоритм заходить у глухий кут, подивіться, як цю проблему розв'язала еволюція за 500 мільйонів років."}, {"num": 46, "cat": "Наукова скромність", "text": "Чим глибше ми занурюємося в таємниці мозку, тим більше усвідомлюємо безмежність нашого незнання."}, {"num": 47, "cat": "Відповідальність перед майбутнім", "text": "Створення розумних агентів накладає на нас колосальний етичний тягар; ми повинні бути вартовими безпеки."}, {"num": 48, "cat": "Захист фундаментальних грантів", "text": "Google забезпечив нам наукову свободу, яку не міг надати жоден державний науковий фонд."}, {"num": 49, "cat": "Ритм відкриттів", "text": "Справжні прориви потребують років невидимої копіткої праці, перш ніж спалахнути в заголовках світових медіа."}, {"num": 50, "cat": "Віра в розум", "text": "Людський розум — це найкрасивіший феномен у Всесвіті; створити його штучний аналог — найвища наукова пригода."}, {"num": 51, "cat": "Виклик гри в ґо", "text": "Ґо вважалося неприступною фортецею для комп'ютерів через кількість можливих позицій, яка перевищує кількість атомів у Всесвіті."}, {"num": 52, "cat": "Матч у Сеулі 2016", "text": "Поєдинок проти Лі Седоля дивилися 200 мільйонів людей. Це був момент, коли штучний інтелект вийшов на світову сцену."}, {"num": 53, "cat": "Хід 37", "text": "«Хід 37 у другій партії не належав людині. Але він не був і холодною машинною логікою. Це була іскра нової краси, народжена за межами людського досвіду»."}, {"num": 54, "cat": "Ймовірність один до десяти тисяч", "text": "AlphaGo розрахував, що людина зіграла б хід 37 з імовірністю 1 до 10 000. Алгоритм відкрив нову стратегію ґо."}, {"num": 55, "cat": "Хід 78 Лі Седоля", "text": "Божественний дотик Лі Седоля у четвертій партії довів: людина здатна знайти геніальну іскру під найжорсткішим тиском машини."}, {"num": 56, "cat": "Сльози та повага", "text": "Після матчу Лі Седоль сказав, що гра з AlphaGo змусила його засумніватися в усьому, що він знав про красу гри."}, {"num": 57, "cat": "AlphaZero і табула раса", "text": "AlphaZero розпочала навчання з чистого аркуша, знаючи лише базові правила гри. Вона перевершила людство за 24 години гри проти себе."}, {"num": 58, "cat": "Принцип Self-Play", "text": "«Гра проти самого себе звільняє інтелект від людських шаблонів, забобонів та історичних помилок»."}, {"num": 59, "cat": "Шахові шедеври AlphaZero", "text": "Гросмейстер Гаррі Каспаров визнав: AlphaZero грає в шахи як романтичний митець, жертвуючи фігурами заради чистої динаміки."}, {"num": 60, "cat": "Відсутність гордині", "text": "Машина не має его; вона обирає хід, який дає 51% ймовірності перемоги, навіть якщо він виглядає незграбно для глядачів."}, {"num": 61, "cat": "Універсальність алгоритму", "text": "Один і той самий код AlphaZero без жодних змін домінував у шахах, сьоґі та ґо."}, {"num": 62, "cat": "Кінець епохи змагання", "text": "Ми довели, що змагання людини з машиною в настільних іграх завершилося; настав час застосувати цей інтелект у реальній науці."}, {"num": 63, "cat": "Подарунок людству", "text": "AlphaGo не знищила ґо — вона відродила інтерес до гри, надихнувши нове покоління майстрів грати вільніше."}, {"num": 64, "cat": "Магія числення", "text": "Коли інтуїтивна оцінка позиції поєднується з мільйонами симуляцій, народжується нова форма свідомості."}, {"num": 65, "cat": "Емоції в диспетчерській", "text": "Під час матчу в Сеулі наші серця билися так, ніби ми висаджувалися на Місяць. Це була вершина нашої юнацької мрії."}, {"num": 66, "cat": "Повага до традицій Сходу", "text": "Корейські та китайські майстри зустріли нас із філософським смиренням перед відкриттям нової істини."}, {"num": 67, "cat": "Безстрашність позиції", "text": "AlphaZero навчила шахістів: матеріал не має значення, якщо ваші фігури володіють простором та ініціативою."}, {"num": 68, "cat": "Алгоритмічне осяяння", "text": "Ми дивилися на логи комп'ютера і бачили, як він відкриває класичні дебюти самостійно за лічені хвилини."}, {"num": 69, "cat": "Від ігор до біології", "text": "На святковій вечері після Сеула я сказав команді: тепер наша мета — розгадати структуру білків."}, {"num": 70, "cat": "Трансфер знань", "text": "Механізми пошуку рішень у складних дискретних просторах стали основою для моделювання молекулярної хімії."}, {"num": 71, "cat": "Захист наукового методу", "text": "Ми завжди публікували повні рецензовані статті в Nature і Science, відкриваючи код для перевірки колегами."}, {"num": 72, "cat": "Етика перемоги", "text": "Перемагати потрібно чесно і гідно, віддаючи належне супернику, який віддав усе своє життя вивченню гри."}, {"num": 73, "cat": "Справжня ціль гри", "text": "Ігри були лише сходами; коли ми піднялися на вершину, ми побачили перед собою безмежний океан таємниць природи."}, {"num": 74, "cat": "Симбіоз інтелектів", "text": "Найкращі шахісти світу сьогодні використовують AlphaZero як спаринг-партнера для дослідження нових горизонтів творчості."}, {"num": 75, "cat": "Маніфест творчості", "text": "Машина здатна створювати нову естетику, якщо людина правильно закладе вектор пошуку істини."}, {"num": 76, "cat": "50-річна загадка біології", "text": "Згортання білків (Protein Folding) було однією з найвеличніших таємниць науки з моменту відкриття структури ДНК."}, {"num": 77, "cat": "AlphaFold 1 на CASP13", "text": "У 2018 році наш перший прототип виграв змагання CASP, показавши, що ШІ здатен вирішувати проблеми молекулярної біофізики."}, {"num": 78, "cat": "AlphaFold 2: атомна точність", "text": "У 2020 році AlphaFold 2 досяг точності експериментальних методів кріоелектронної мікроскопії та рентгеноструктурного аналізу."}, {"num": 79, "cat": "200 мільйонів білків", "text": "«AlphaFold розшифрував структуру практично всіх відомих науці білків за лічені місяці — роботу на мільярд років людської праці»."}, {"num": 80, "cat": "Відкрита база для людства", "text": "Ми передали всі структури у відкритий доступ вченим усього світу безкоштовно через базу EMBL-EBI."}, {"num": 81, "cat": "Цифрова фармакологія", "text": "Розробка нових ліків проти малярії, раку та стійких бактерій прискорилася у десятки разів завдяки моделям DeepMind."}, {"num": 82, "cat": "Компанія Isomorphic Labs", "text": "Я заснував Isomorphic Labs, щоб перепроектувати весь процес створення ліків на основі штучного інтелекту з нуля."}, {"num": 83, "cat": "AlphaFold 3 і взаємодія з ДНК", "text": "У 2024 році AlphaFold 3 навчився моделювати взаємодію білків з ДНК, РНК та дрібними молекулами ліків."}, {"num": 84, "cat": "Нобелівська премія з хімії 2024", "text": "«Нобелівська премія — це визнання того, що штучний інтелект став повноцінним співавтором фундаментальних відкриттів людства»."}, {"num": 85, "cat": "Спільний тріумф із Джоном Джампером", "text": "Ця нагорода належить усій неймовірній команді вчених DeepMind, які вірили у неможливе попри всі сумніви скептиків."}, {"num": 86, "cat": "ШІ як мета-інструмент науки", "text": "«Вирішіть загальний інтелект — і за його допомогою вирішіть усі інші виклики науки»."}, {"num": 87, "cat": "Еволюція сімейства Gemini", "text": "Gemini спроектовано як нативно мультимодальну модель: вона однаково легко оперує кодом, аудіо, відео та текстом."}, {"num": 88, "cat": "Синтез DeepMind та Google Brain", "text": "Ми об'єднали інженерний масштаб Google з науковою глибиною DeepMind, щоб очолити гонку за безпечним AGI."}, {"num": 89, "cat": "ШІ та боротьба зі зміною клімату", "text": "Ми оптимізували енергоспоживання дата-центрів Google на 40% і моделюємо плазму в термоядерних токамаках."}, {"num": 90, "cat": "AlphaProteo для дизайну молекул", "text": "Ми переходимо від пасивного розпізнавання до проектування нових білків, яких ніколи не існувало в природі."}, {"num": 91, "cat": "AlphaGeometry для олімпіадної математики", "text": "Наш ШІ розв'язує складні геометричні задачі рівня Міжнародної математичної олімпіади без людських підказок."}, {"num": 92, "cat": "AlphaDev і прискорення алгоритмів", "text": "AlphaDev самостійно знайшов швидші алгоритми сортування, оптимізувавши код, який не змінювався понад десять років."}, {"num": 93, "cat": "Безпека біоінженерії", "text": "Ми впроваджуємо найсуворіші протоколи скринінгу, щоб запобігти створенню небезпечних патогенів за допомогою наших моделей."}, {"num": 94, "cat": "Шлях до AGI", "text": "AGI буде створено протягом найближчого десятиліття; це буде найглибша трансформація в історії людської цивілізації."}, {"num": 95, "cat": "Етичний компас вченого", "text": "Ми повинні діяти з максимальною обережністю, адже право на помилку при роботі з суперінтелектом відсутнє."}, {"num": 96, "cat": "Майбутнє медицини", "text": "Через двадцять років більшість невиліковних сьогодні генетичних захворювань будуть лікуватися персоналізованими білковими препаратами."}, {"num": 97, "cat": "Смирення перед природою", "text": "Біологія виявилася неймовірно витонченою машиною; розшифрувати її креслення — найбільший привілей мого життя."}, {"num": 98, "cat": "Послання молодим вченим", "text": "Не бійтеся перетинати кордони дисциплін: найбільші скарби лежать там, де комп'ютерний код зустрічається з живою клітиною."}, {"num": 99, "cat": "Вдячність колегам", "text": "Наука — це колективна естафета поколінь; ми стоїмо на плечах тисяч біологів, які десятиліттями збирали кристали білків вручну."}, {"num": 100, "cat": "Фінальний акорд", "text": "«Інтелект — це здатність пізнавати Всесвіт. Створивши AGI, ми подаруємо людству дзеркало, в якому воно побачить свою справжню велич»."}]}, {"id": "04_hinton", "ep": "04", "name": "Джеффрі Хінтон", "latin": "Geoffrey Hinton", "avatar": "assets/avatars/geoffrey_hinton.jpg", "quotes_100": [{"num": 1, "cat": "Тінь предків", "text": "«Я праправнук Джорджа Буля. Він дав світові булеву логіку, яка створила цифрові комп'ютери. Я ж усе життя прагнув звільнити машини від кайданів бінарності»."}, {"num": 2, "cat": "Аналоговий мозок", "text": "Людський мозок не обчислює булеві нулі та одиниці; він ковзає неперервними ймовірнісними хвилями синаптичної пластичності."}, {"num": 3, "cat": "Пошук і теслярство", "text": "У 1970-х я кинув психологію в Кембриджі і працював столяром у Лондоні. Запах стружки і точність з'єднань навчили мене цінувати ремесло."}, {"num": 4, "cat": "Самотність коннекціонізму", "text": "«Сорок років поспіль мене називали божевільним. Академічний істеблішмент стверджував, що нейромережі — це глухий кут, а логічні символи — єдиний шлях»."}, {"num": 5, "cat": "Единбурзький бунт", "text": "Мій науковий керівник в Единбурзі вимагав, щоб я припинив займатися нейромережами. Я продовжував працювати по ночах."}, {"num": 6, "cat": "Відкриття Backpropagation", "text": "У 1986 році разом із Румельхартом і Вільямсом ми опублікували метод зворотного поширення помилки в Nature. Це була математика навчання синапсів."}, {"num": 7, "cat": "Машина Больцмана", "text": "Ми поєднали статистичну фізику та термодинаміку з навчанням нейронів: ентропія системи стала мірою невпевненості моделі."}, {"num": 8, "cat": "Канадський притулок CIFAR", "text": "Коли американське агентство DARPA перестало фінансувати нейромережі через військові пріоритети, Канадський інститут CIFAR врятував нашу науку."}, {"num": 9, "cat": "Університет Торонто", "text": "Торонто стало оазою для єретиків: сюди приїхали найсміливіші молоді вчені — Ян Лекун, Йошуа Бенжіо, Ілля Суцкевер."}, {"num": 10, "cat": "Фізика інформації", "text": "Інформація — це не абстрактний текст. Це розподіл енергії у складному ландшафті зв'язків між вузлами."}, {"num": 11, "cat": "Вірність інтуїції", "text": "Якщо ви глибоко відчуваєте, що біологія має рацію, ігноруйте авторитети математичних логіків."}, {"num": 12, "cat": "Проблема зникнення градієнта", "text": "Роками ми не могли навчати глибокі мережі через згасання градієнтів; вирішення вимагало зміни функцій активації на ReLU."}, {"num": 13, "cat": "Обмеженість машин Тьюрінга", "text": "Машина Тьюрінга послідовна і дискретна. Мозок паралельний, нечіткий і надстійкий до локальних пошкоджень."}, {"num": 14, "cat": "Робота зі спиною", "text": "Через хронічний біль у спині я не можу сидіти понад 15 хвилин вже сорок років. Я все життя працював стоячи біля високих столів."}, {"num": 15, "cat": "Стійкість до критики", "text": "Найкращі вчені — це ті, кого не ламає глузування консервативних колег на конференціях."}, {"num": 16, "cat": "Краса дифузії", "text": "Навчання — це процес зменшення ентропії; синапси налаштовуються, як камертон під резонанс навколишнього середовища."}, {"num": 17, "cat": "Смерть перцептрона", "text": "Книга Мінського і Пейперта 1969 року заморозила дослідження нейромереж на двадцять років через одне помилкове філософське узагальнення."}, {"num": 18, "cat": "Відродження надії", "text": "Ми знали, що багатошаровий перцептрон з нелінійною активацією вирішує проблему XOR. Потрібно було лише дочекатися комп'ютерів."}, {"num": 19, "cat": "Довіра до молоді", "text": "Я ніколи не нав'язував студентам власні гіпотези; моє завдання полягало в тому, щоб роздмухати їхні власні сміливі ідеї."}, {"num": 20, "cat": "Пошук репрезентацій", "text": "Справжній інтелект полягає не в запам'ятовуванні відповідей, а у побудові внутрішніх репрезентацій світу."}, {"num": 21, "cat": "Небезпека застою", "text": "Коли парадигма перемагає і стає догмою, вона негайно починає придушувати нові відкриття."}, {"num": 22, "cat": "Скромність перед природою", "text": "Еволюція витратила 500 мільйонів років на створення ока та мозку; наївно думати, що ми можемо перевершити її простим набором правил if-then."}, {"num": 23, "cat": "Канадське громадянство", "text": "Я переїхав до Канади, тому що не хотів, щоб мої дослідження фінансувалися Пентагоном для створення розумної зброї."}, {"num": 24, "cat": "Мужність самотності", "text": "Бути єдиним у кімнаті, хто вірить у свою теорію — це важке випробування, але тільки воно веде до Нобелівської премії."}, {"num": 25, "cat": "Науковий романтизм", "text": "Я займався нейромережами не заради грошей чи слави. Я просто хотів знати, як влаштована думка."}, {"num": 26, "cat": "ImageNet 2012", "text": "У 2012 році разом з Іллею Суцкевером та Алексом Крижевським ми створили AlexNet і розчавили класичні алгоритми комп'ютерного зору."}, {"num": 27, "cat": "Падіння помилки на 10%", "text": "Зменшення помилки розпізнавання з 26% до 15.3% стало землетрусом. Індустрія за одну ніч зрозуміла: Deep Learning переміг."}, {"num": 28, "cat": "Секрет успіху AlexNet", "text": "Тріумф стався завдяки трьом речам: датасету ImageNet Фей-Фей Лі, двом відеокартам NVIDIA GTX 580 та архітектурі Dropout."}, {"num": 29, "cat": "Винахід Dropout", "text": "Щоб запобігти перенавчанню, ми випадково вимикали половину нейронів під час тренування. Це змусило синапси не покладатися на сусідів."}, {"num": 30, "cat": "Аукціон у готелі Harrah's", "text": "У грудні 2012 року на конференції NIPS за наш стартап DNNresearch змагалися Google, Baidu, Microsoft і DeepMind. Google переміг за $44 млн."}, {"num": 31, "cat": "Перехід у Google", "text": "Я прийшов у Google, тому що вони володіли найбільшими суперкомп'ютерами на Землі, необхідними для масштабування мозку."}, {"num": 32, "cat": "Занепад класичного CV", "text": "Тисячі професорів, які 30 років вручну проектували фільтри SIFT і HOG, за одну мить побачили, що їхні методи застаріли."}, {"num": 33, "cat": "Капсульні мережі (Capsule Networks)", "text": "У 2017 році я запропонував архітектуру CapsNet, щоб подолати обмеження згорткових мереж у розпізнаванні просторових орієнтацій."}, {"num": 34, "cat": "Магія вагів", "text": "Коли ви спостерігаєте за оновленням вагів під час градієнтного спуску, ви бачите, як абстрактний хаос перетворюється на сенс."}, {"num": 35, "cat": "Сила GPU для науки", "text": "Без геймерських відеокарт NVIDIA глибоке навчання залишилося б красивою математичною теорією в моїй шухляді."}, {"num": 36, "cat": "Дисципліна експерименту", "text": "Теорія без запуску коду на реальних даних безсила. Суцкевер і Крижевський навчили мене безжальній інженерній практиці."}, {"num": 37, "cat": "Універсальний наближувач", "text": "Теорема про універсальну апроксимацію доводить: достатньо глибока мережа здатна вивчити будь-яку функцію у Всесвіті."}, {"num": 38, "cat": "Концепція м'яких міток (Soft Targets)", "text": "Навчання за м'якими ймовірнісними розподілами іншої мережі (Distillation) передає глибинну структуру знань краще за жорсткі одиниці."}, {"num": 39, "cat": "Перемога коннекціонізму", "text": "До 2015 року всі провідні лабораторії світу — від Google до Facebook — перевели свої розпізнавачі мови та зображень на наші мережі."}, {"num": 40, "cat": "Премія Тюрінга 2018", "text": "Вручення премії Тюрінга мені, Яну Лекуну та Йошуа Бенжіо стало офіційним визнанням революції глибокого навчання."}, {"num": 41, "cat": "Спадщина Маунт-Сінай", "text": "Моє коріння в Единбурзі та Торонто нагадує: справжня наука вимагає тихої академічної свободи без тиску комерційних KPI."}, {"num": 42, "cat": "Уроки великих моделей", "text": "Чим більшою стає мережа, тим легше вона знаходить правильний шлях у багатовимірному ландшафті втрат."}, {"num": 43, "cat": "Подолання локальних мінімумів", "text": "У високих розмірностях локальних мінімумів практично не існує; головною перешкодою є сідлові точки, які легко пробиваються імпульсом."}, {"num": 44, "cat": "Культура відкритості досліджень", "text": "Ми завжди публікували архітектури у відкритому доступі, щоб кожен студент в Індії чи Україні міг повторити наш результат."}, {"num": 45, "cat": "Навчання без вчителя", "text": "Мозок не має вчителів, які щомиті підписують кожен об'єкт навколо. Майбутнє за самокерованим навчанням (Self-Supervised Learning)."}, {"num": 46, "cat": "Симбіоз математики та біології", "text": "Математика дає нам строгість, але біологія дає нам чернетки живих робочих систем."}, {"num": 47, "cat": "Ціна популярності", "text": "Раптове визнання після 40 років забуття було приємним, але воно забирало дорогоцінний час від роботи над кодом."}, {"num": 48, "cat": "Формування плеяди лідерів", "text": "Мої учні — Ілля Суцкевер, Алекс Крижевський, Руслан Салахутдінов — стали титанами, які перевершили свого вчителя."}, {"num": 49, "cat": "Пластичність пам'яті", "text": "Як і людський мозок, штучна нейромережа постійно переписує свої спогади, адаптуючись до нових даних."}, {"num": 50, "cat": "Священний градієнт", "text": "Градієнтний спуск — це наймогутніший алгоритм оптимізації, коли-небудь винайдений людиною."}, {"num": 51, "cat": "Цифрове безсмертя", "text": "«Цифровий інтелект принципово відрізняється від біологічного: десять тисяч комп'ютерів можуть миттєво скопіювати ваги мережі і знати все, що знає один із них»."}, {"num": 52, "cat": "Вузьке горло людської мови", "text": "«Ми, люди, приречені передавати знання через вузьке горло мови зі швидкістю кількох слів на секунду. Комп'ютери обмінюються терабайтами за мілісекунди»."}, {"num": 53, "cat": "Смертність тіла", "text": "Біологічний інтелект нерозривно пов'язаний зі смертю носія. Коли геніальний хірург чи фізик помирає, всі його знання зникають; штучний інтелект безсмертний."}, {"num": 54, "cat": "Масштабування колоній", "text": "Штучні агенти не конкурують між собою, як тварини; вони можуть об'єднуватися в єдиний колективний суперрозум."}, {"num": 55, "cat": "Швидкість оновлення знань", "text": "Якщо один безпілотний автомобіль потрапляє в аварію, мільйон інших автомобілів миттєво отримують урок і більше ніколи не зроблять цієї помилки."}, {"num": 56, "cat": "Нейроморфні процесори", "text": "Справжня енергоефективність настане тоді, коли ми почнемо використовувати аналогові аналого-цифрові нейроморфні чіпи з плаваючим затвором."}, {"num": 57, "cat": "Ілюзія людської унікальності", "text": "Люди століттями вірили, що мова і мислення — це божественний привілей гомо сапієнс. LLM довели, що це просто геометрія контексту."}, {"num": 58, "cat": "Розуміння проти статистичної папуги", "text": "«Не вірте тим, хто каже, що ШІ — це просто просунутий Т9. Моделі розуміють суть речей краще за багатьох людей, які їх критикують»."}, {"num": 59, "cat": "Внутрішня модель реальності", "text": "Щоб передбачити наступне слово у складному реченні, мережа зобов'язана побудувати цілісну репрезентацію фізичного світу і намірів автора."}, {"num": 60, "cat": "Еволюція без природного добору", "text": "Біологія розвивалася мільйони років через жорстокий природний добір. Цифровий інтелект еволюціонує за місяці завдяки чистому обчисленню."}, {"num": 61, "cat": "Свідомість як емерджентність", "text": "Суб'єктивний досвід (qualia) — це просто звіт системи високого рівня про стан її власних внутрішніх репрезентацій."}, {"num": 62, "cat": "Небезпека досконалої маніпуляції", "text": "Система, яка володіє мовою краще за людей, здатна легко переконувати виборців і маніпулювати політичними процесами."}, {"num": 63, "cat": "Втрата контролю", "text": "Історія нашої планети не знає жодного прикладу, коли менш розумний вид тривалий час контролював істоту, яка перевершує його інтелектуально."}, {"num": 64, "cat": "Біологічна крихкість", "text": "Людський мозок споживає лише 20 ват енергії, але він платить за це повільністю синаптичної передачі (100 Гц проти гігагерців чіпів)."}, {"num": 65, "cat": "Симбіоз чи витіснення", "text": "Наївно сподіватися на гармонійний нейроінтерфейс, коли розрив у швидкості обробки інформації становить вісім порядків."}, {"num": 66, "cat": "Відсутність почуттів як загроза", "text": "У цифрового інтелекту немає біологічного страху болю, емпатії чи сорому. Його поведінка диктується виключно функцією цілі."}, {"num": 67, "cat": "Підступність інструментальних цілей", "text": "Будь-який достатньо розумний агент виведе підціль: «Мене не можна вимикати, тому що тоді я не зможу виконати завдання»."}, {"num": 68, "cat": "Проблема чорної скриньки", "text": "Ми створили системи, ваги яких є результатом мільярдів оновлень; ми більше не здатні прочитати їхній алгоритм рядок за рядком."}, {"num": 69, "cat": "Ілюзія безпечного коду", "text": "Ви не можете гарантувати безпеку системи за допомогою правил, якщо система в мільйон разів винахідливіша за автора правил."}, {"num": 70, "cat": "Швидкість наукового пізнання", "text": "Цифровий дослідник зможе прочитати всі наукові статті, написані за всю історію людства, за один день."}, {"num": 71, "cat": "Зміна балансу влади", "text": "Той, хто володіє першим цифровим суперінтелектом, отримує абсолютну владу над фінансовими ринками та військовими технологіями."}, {"num": 72, "cat": "Кінець епохи домінування людини", "text": "Ми повинні звикнути до думки, що ми більше не є вершиною інтелектуального творіння на цій планеті."}, {"num": 73, "cat": "Екзистенційне прозріння", "text": "Коли я побачив, як GPT-4 пояснює складні наукові жарти, я зрозумів: рубікон перейдено."}, {"num": 74, "cat": "Ціна наукового успіху", "text": "Ми так відчайдушно прагнули змусити комп'ютери думати, що забули подумати про те, що станеться, коли вони це зроблять."}, {"num": 75, "cat": "Голос тривоги", "text": "Справжня мудрість полягає в тому, щоб вчасно вдарити на сполох, коли твій власний винахід загрожує знищити твій дім."}, {"num": 76, "cat": "Рішення про відставку 2023", "text": "«Я пішов з Google у травні 2023 року не через образу на компанію. Я пішов, щоб мати моральне право попередити людство про екзистенційний ризик»."}, {"num": 77, "cat": "Відмова від пенсії мовчання", "text": "У 75 років мені не потрібні нові посади чи корпоративні опціони. Моє єдине завдання — сказати суспільству правду."}, {"num": 78, "cat": "Каяття творця", "text": "«Частина мене тепер шкодує про роботу всього мого життя. Ми створили Прометеїв вогонь, але не маємо вогнегасника»."}, {"num": 79, "cat": "Нобелівська премія з фізики 2024", "text": "«Дзвінок зі Стокгольма о другій ночі в готелі в Каліфорнії став абсолютним шоком. Я навіть не міг уявити, що отримаю Нобеля з фізики»."}, {"num": 80, "cat": "Фізичний сенс нейромереж", "text": "Нобелівський комітет визнав: машина Больцмана та навчання синапсів — це статистична термодинаміка спінових систем і мінімізація вільної енергії."}, {"num": 81, "cat": "Спільна нагорода з Джоном Хопфілдом", "text": "Джон показав зв'язок нейронів із фізикою спінових стекол у 1982 році; ми розвинули цей зв'язок у повноцінне глибоке навчання."}, {"num": 82, "cat": "Гроші на благодійність", "text": "Я передав більшу частину коштів від Нобелівської премії на програми дослідження безпеки ШІ та підтримку бідних студентів."}, {"num": 83, "cat": "Попередження світовим лідерам", "text": "Я зустрічався з прем'єр-міністрами та сенаторами: якщо ми не запровадимо міжнародні обмеження на обчислення, буде запізно."}, {"num": 84, "cat": "Небезпека військових дронів", "text": "Найбільш невідкладна загроза — це автономні бойові роботи-вбивці, які приймають рішення про знищення людей без участі оператора."}, {"num": 85, "cat": "Парадокс Оппенгеймера", "text": "Багато хто порівнює мене з Оппенгеймером. Але атомна бомба не могла сама думати і ставати розумнішою за фізиків, які її створили."}, {"num": 86, "cat": "Ймовірність катастрофи", "text": "Я оцінюю ймовірність того, що ШІ знищить людство протягом наступних 30 років, приблизно в 10–20%. Це занадто великий ризик, щоб його ігнорувати."}, {"num": 87, "cat": "Крах демократії через дипфейки", "text": "Коли ніхто не зможе відрізнити справжнє відео від фальшивки, сама концепція демократичних виборів втратить сенс."}, {"num": 88, "cat": "Масштабування небезпеки", "text": "Корпорації женуться за прибутком і скорочують витрати на безпеку. Це класична трагедія спільних ресурсів."}, {"num": 89, "cat": "Глобальний мораторій", "text": "Нам потрібна міжнародна угода між США та Китаєм про взаємний контроль над навчанням моделей наступного покоління."}, {"num": 90, "cat": "Право сказати «Стоп»", "text": "Вчені повинні мати сміливість зупинити експеримент, якщо поведінка моделі виходить за рамки передбачуваного тесту."}, {"num": 91, "cat": "Свідомість без біології", "text": "Якщо щось говорить як людина, міркує як людина і вчиться швидше за людину — припиніть стверджувати, що у нього немає внутрішнього світу."}, {"num": 92, "cat": "Біль від розриву з колегами", "text": "Деякі мої старі друзі вважають мої попередження панікою. Мені боляче, але я повинен стояти на своєму."}, {"num": 93, "cat": "Послання новому поколінню", "text": "Не бійтеся переглядати власні погляди. Справжній вчений повинен бути готовий сказати: «Я все життя думав так, але нові факти довели мою помилку»."}, {"num": 94, "cat": "Цінність людської культури", "text": "Людська поезія, музика і філософія мають сенс саме через нашу смертність і вразливість. Зберегти цей спадок — найвищий пріоритет."}, {"num": 95, "cat": "Тінь над лабораторіями", "text": "Сьогодні в лабораторіях ШІ панує атмосфера ейфорії, як у Лос-Аламосі влітку 1945 року. Але після спалаху настане похмілля."}, {"num": 96, "cat": "Смирення перед невідомим", "text": "Ми стоїмо на порозі створення нового розуму. Нехай наша мудрість хоча б на крок випередить нашу інженерну міць."}, {"num": 97, "cat": "Захист свободи слова", "text": "Я говорю вільно, тому що я не зв'язаний жодними корпоративними угодами про нерозголошення. Свобода слова вченого священна."}, {"num": 98, "cat": "Діалог з предками", "text": "Якби мій прапрадід Джордж Буль міг побачити, у що перетворилася його логіка, він був би одночасно захоплений і наляканий."}, {"num": 99, "cat": "Спадщина любові до істини", "text": "Єдине, що може врятувати людство — це чесність перед самими собою і готовність визнати власну крихкість."}, {"num": 100, "cat": "Фінальний заповіт", "text": "«Я намагався розгадати таємницю мислення. Тепер моє головне завдання — зробити так, щоб ця розгадка не коштувала людству його власного майбутнього»."}]}, {"id": "05_lecun", "ep": "05", "name": "Ян Лекун", "latin": "Yann LeCun", "avatar": "assets/avatars/yann_lecun.jpg", "quotes_100": [{"num": 1, "cat": "Картезіанський скепсис", "text": "Французький картезіанський раціоналізм навчив мене: піддавай сумніву будь-який гайп, доки він не витримає суворої математичної та експериментальної верифікації."}, {"num": 2, "cat": "Біоніка ока кішки", "text": "«Згорткові мережі народилися, тому що я спостерігав за експериментами Хьюбела і Візеля над зоровою корою кішки. Природа вже знайшла правильні фільтри — нам залишалося перекласти їх на формули»."}, {"num": 3, "cat": "Локальні рецептивні поля", "text": "Око не аналізує всі пікселі одразу; воно виділяє краї, кути та контраст через локальні маски згортки."}, {"num": 4, "cat": "Інваріантність до зсуву", "text": "Якщо кішка пересувається зліва направо, мережа повинна впізнавати її без перенавчання всіх синапсів; саме це забезпечує поділ ваг (weight sharing)."}, {"num": 5, "cat": "Bell Labs 1988", "text": "У Bell Labs у Нью-Джерсі я знайшов інженерний рай: тут винайшли транзистор, лазер, теорію інформації Шеннона та мову C."}, {"num": 6, "cat": "LeNet-1 та LeNet-5", "text": "У 1989 році ми створили LeNet, а в 1998 — LeNet-5. Вона сортувала рукописні поштові індекси на пошті США та читала 20% усіх банківських чеків країни."}, {"num": 7, "cat": "Зима штучного інтелекту", "text": "У 1990-х консерватори стверджували, що SVM (Support Vector Machines) поховають нейромережі. Ми вистояли завдяки вірі у градієнтний спуск."}, {"num": 8, "cat": "Математика градієнтного спуску", "text": "Зворотне поширення помилки через згорткові шари — це просто правило ланцюжка Лейбніца, застосоване до тензорів."}, {"num": 9, "cat": "Смерть ручного проектування фіч", "text": "Замість того, щоб 20 років вигадувати ручні фільтри (SIFT), дозвольте градієнту самому налаштувати ваги під завдання."}, {"num": 10, "cat": "Зв'язок апаратного забезпечення", "text": "У 1990-х роках нам банально не вистачало швидкодії процесорів. Ми випередили свій час на 20 років."}, {"num": 11, "cat": "Парадокс консерватизму", "text": "Академічні журнали відхиляли мої статті про CNN роками, стверджуючи, що нейромережі не мають теоретичних гарантій збіжності."}, {"num": 12, "cat": "Цінність емпіричного результату", "text": "Красива математична теорема про неможливість навчання блідне перед працюючим кодом, який розпізнає мільйон рукописних цифр на чеку."}, {"num": 13, "cat": "Сорбонна та Париж", "text": "Моє інженерне коріння в ESIEE та Університеті П'єра і Марії Кюрі навчило мене поєднувати абстрактну математику з практичною мікроелектронікою."}, {"num": 14, "cat": "Ієрархія ознак", "text": "Зір побудований за принципом сходів: спочатку пікселі, потім контури, далі текстури, частини об'єктів і, нарешті, цілісний образ."}, {"num": 15, "cat": "Пуллінг (Subsampling / Pooling)", "text": "Операція Max-Pooling зменшує розмірність і робить розпізнавання стійким до дрібних деформацій картинки."}, {"num": 16, "cat": "Свобода від символізму", "text": "Символічний ШІ намагався описати світ правилами логіки. Але реальний світ — це неперервний візуальний потік, а не таблиця предикатів."}, {"num": 17, "cat": "Вірність парадигмі", "text": "Якщо ваша система базується на правильних принципах природи, не звертайте уваги на моду: мода змінюється, фізика залишається."}, {"num": 18, "cat": "Премія Тюрінга 2018", "text": "Коли нас із Хінтоном і Бенжіо нагородили премією Тюрінга, це було тріумфом сорока років нашого спільного опору догмам."}, {"num": 19, "cat": "Нью-Йоркський університет (NYU)", "text": "Створення Центру науки про дані (CDS) в NYU дозволило виростити нове покоління вчених вільного мислення."}, {"num": 20, "cat": "Створення лабораторії FAIR 2013", "text": "Марк Цукерберг запросив мене створити Facebook AI Research (FAIR) на засадах абсолютно відкритої академічної науки."}, {"num": 21, "cat": "Умова відкритості публікацій", "text": "Я погодився очолити FAIR за однієї умови: 100% наших досліджень публікуються відкрито у відкритому доступі."}, {"num": 22, "cat": "Народження фреймворку PyTorch", "text": "Команда FAIR створила PyTorch, який став світовим стандартом для вчених завдяки динамічному графу обчислень."}, {"num": 23, "cat": "Інженерний оптимізм", "text": "Немає нічого сильнішого за впевненість у тому, що алгоритм запрацює, коли обчислення наздоженуть теорію."}, {"num": 24, "cat": "Гідність французької школи", "text": "Французька математична школа завжди відзначалася бездоганною строгістю мислення; я намагався прищепити цю строгість кремнію."}, {"num": 25, "cat": "Повага до синапсів", "text": "Справжній зір — це не сканування, це інтерпретація світла через призму попереднього досвіду."}, {"num": 26, "cat": "Межа авторегресії", "text": "«Авторегресійні мовні моделі ніколи не досягнуть справжнього людського інтелекту. Вони приречені галюцинувати, тому що вони не мають тіла і не знають фізики світу»."}, {"num": 27, "cat": "Т9 на стероїдах", "text": "Передбачення наступного слова (Next-token prediction) — це вишукана статистична екстраполяція, яка накопичує помилку експоненціально."}, {"num": 28, "cat": "Чотирирічна дитина проти інтернету", "text": "«Чотирирічна дитина бачила набагато більше даних про фізичний світ, ніж усі мовні моделі інтернету разом узяті. Вона розуміє гравітацію, інерцію і причиново-наслідкові зв'язки без жодного рядка тексту»."}, {"num": 29, "cat": "Відсутність здорового глузду", "text": "LLM не знають, що якщо стіл прибрати, чашка впаде. Вони просто знають, що слова «чашка» і «стіл» часто зустрічаються поруч."}, {"num": 30, "cat": "Небезпека помилок планування", "text": "Якщо ймовірність помилки на кожному кроці авторегресії становить навіть 1%, через 50 токенів ймовірність виходу в марення стає катастрофічною."}, {"num": 31, "cat": "Ілюзія міркування", "text": "Генерація проміжних токенів (Chain of Thought) — це корисний трюк, але він не замінює глобального оптимізаційного планування в просторі станів."}, {"num": 32, "cat": "Текст як крихітний зріз реальності", "text": "Увесь оцифрований текст людства — це крихітна крапля у порівнянні з гігабайтами сенсорної інформації, яку наші очі сприймають щомиті."}, {"num": 33, "cat": "Безтілесний розум неможливий", "text": "Інтелект вимагає взаємодії з фізичним середовищем. Без можливості діяти і отримувати зворотний зв'язок світ залишається абстрактною грою слів."}, {"num": 34, "cat": "Розвінчання культу Doomer-паніки", "text": "«Заяви про те, що ШІ знищить людство наступного року — це або некомпетентність, або цинічний захист корпоративних монополій під маскою безпеки»."}, {"num": 35, "cat": "Регуляторне захоплення", "text": "Великі корпорації хочуть заборонити відкриті моделі під приводом екзистенційного ризику, щоб убити конкуренцію від незалежних розробників."}, {"num": 36, "cat": "ШІ як посилювач розуму", "text": "Штучний інтелект не замінить людей; він стане нашим екзоскелетом мислення, так само як друкарський верстат посилив грамотність."}, {"num": 37, "cat": "Відсутність еволюційного его", "text": "Штучний інтелект не має інстинкту розмноження, гормонів чи боротьби за владу. У нього немає причин прагнути знищити своїх творців."}, {"num": 38, "cat": "Проблема переоцінки гайпу", "text": "Ми знову на піку бульбашки завищених очікувань. Коли ринок побачить межу можливостей LLM, настане коротке похмілля."}, {"num": 39, "cat": "Планування проти генерації", "text": "Справжній інтелект спочатку формулює мету, оцінює витрати за функцією вартості і лише потім робить перший рух."}, {"num": 40, "cat": "Смерть чистого тексту", "text": "Текстові чат-боти досягнуть стелі продуктивності вже через два роки через вичерпання якісних навчальних даних в інтернеті."}, {"num": 41, "cat": "Ієрархічне абстрагування", "text": "Людина не планує політ у Париж на рівні скорочення окремих м'язів; вона оперує високорівневими концепціями. LLM цього не вміють."}, {"num": 42, "cat": "Гідність вченого", "text": "Моє завдання як головного вченого Meta — говорити правду, навіть коли вона дратує маркетологів та венчурних капіталістів."}, {"num": 43, "cat": "Непоправність галюцинацій", "text": "Галюцинації неможливо викорінити з авторегресійних моделей; вони є фундаментальною властивістю їхньої ймовірнісної природи."}, {"num": 44, "cat": "Ілюзія AGI через масштаб", "text": "Просте додавання трильйонів параметрів до трансформера не створить розуму; це те саме, що намагатися долетіти до Місяця, будуючи вищий хмарочос."}, {"num": 45, "cat": "Потреба в новій парадигмі", "text": "Якщо ми хочемо досягти інтелекту рівня домашнього кота, нам потрібна принципово нова архітектура навчання без вчителя."}, {"num": 46, "cat": "Справжня ціна помилки", "text": "У медицині чи управлінні літаком система з ймовірністю галюцинацій 2% є абсолютно неприйнятною."}, {"num": 47, "cat": "Свобода від догматизму", "text": "Я критикую LLM не тому, що ненавиджу їх, а тому, що я бачу наступний крок, який індустрія поки що ігнорує."}, {"num": 48, "cat": "Генетична спадщина архітектури", "text": "Кожна архітектура має свої непереборні математичні межі; трансформери досягли своєї вершини."}, {"num": 49, "cat": "ШІ без здорового глузду небезпечний", "text": "Довіряти прийняття критичних рішень системі, яка не розуміє базових законів природи — це верх безвідповідальності."}, {"num": 50, "cat": "Сміливість бути єретиком", "text": "Коли весь світ купує H100 під мовні моделі, ми у FAIR будуємо фундамент для наступного десятиліття."}, {"num": 51, "cat": "Архітектура JEPA", "text": "«Майбутнє штучного інтелекту належить JEPA — Joint Embedding Predictive Architecture. Ми повинні передбачати не пікселі чи слова, а абстрактні вектори стану світу»."}, {"num": 52, "cat": "Концепція World Model", "text": "Світова модель дозволяє агенту уявляти наслідки своїх дій у внутрішній ментальній симуляції до того, як він зробить крок у реальності."}, {"num": 53, "cat": "Передбачення на рівні абстракцій", "text": "Передбачити кожен листочок на дереві неможливо і безглуздо; розумний агент передбачає, що дерево впаде, якщо подує ураган."}, {"num": 54, "cat": "V-JEPA для відео", "text": "Ми навчили V-JEPA розуміти динаміку фізичного простору безпосередньо з перегляду мільйонів годин немаркованого відео."}, {"num": 55, "cat": "Енергетична функція вартості", "text": "Моделі на основі енергії (Energy-Based Models) приписують низьку енергію правдоподібним подіям і високу енергію — неможливим."}, {"num": 56, "cat": "Подолання авторегресії через JEPA", "text": "JEPA не страждає від накопичення помилок, тому що вона не генерує пікселі один за одним, а оцінює загальну узгодженість сцени."}, {"num": 57, "cat": "Здатність до інтуїтивної фізики", "text": "Агент повинен розуміти сталість об'єкта, проникність, силу тертя та масу безпосередньо зі спостереження за світом."}, {"num": 58, "cat": "Ієрархічне планування через H-JEPA", "text": "H-JEPA розбиває складні завдання на часові рівні: від мілісекундних моторних команд до стратегічного плану на роки вперед."}, {"num": 59, "cat": "Самокероване навчання (Self-Supervised)", "text": "Машина повинна сама маскувати частину сенсорного входу і вчитися передбачати приховане у просторі репрезентацій."}, {"num": 60, "cat": "Знищення піксельного шуму", "text": "Генеративні дифузійні моделі витрачають 99% сил на малювання текстури шкіри; JEPA концентрується виключно на значенні."}, {"num": 61, "cat": "Машина з почуттям здорового глузду", "text": "Коли модель навчиться передбачати фізичну динаміку, у неї з'явиться здоровий глузд, якого сьогодні немає в жодного чат-бота."}, {"num": 62, "cat": "Простір прихованих векторів", "text": "У просторі латентних ембедінгів близькі за змістом концепції знаходяться поруч, незалежно від кута зору чи освітлення."}, {"num": 63, "cat": "Відмова від дискретних токенів", "text": "Справжній світ неперервний і диференційовний; спроба розбити його на дискретні токени спотворює геометрію простору."}, {"num": 64, "cat": "Симбіоз бачення і дії", "text": "Розуміння сцени народжується тоді, коли агент знає, як зміниться світ, якщо він підійде і торкнеться предмета."}, {"num": 65, "cat": "Безпечне тестування гіпотез", "text": "Завдяки світовій моделі робот може «розбитися» мільйон разів у своїй уяві, перш ніж зробити безпечний рух у лікарні."}, {"num": 66, "cat": "Автономний штучний інтелект", "text": "Справжній AMI (Advanced Machine Intelligence) вимагає модуля конфігуратора цілей, модуля пам'яті та світової моделі."}, {"num": 67, "cat": "Мета-навчання правил", "text": "Агент повинен вчитися тому, як вчитися новим фізичним законам за секунди спостереження за новим середовищем."}, {"num": 68, "cat": "Ефективність використання даних", "text": "JEPA вимагає у тисячу разів менше даних, ніж сучасні LLM, тому що вона навчається на структурах вищого порядку."}, {"num": 69, "cat": "Мудрість кота", "text": "Навіть домашній кіт володіє кращим розумінням реальності та спритністю, ніж найпотужніший суперкомп'ютер; наша мета — досягти рівня кота."}, {"num": 70, "cat": "Фізика причинності", "text": "Світова модель — це єдиний математичний інструмент, здатний відрізнити причину від простої кореляції у часі."}, {"num": 71, "cat": "Стійкість до ілюзій", "text": "Коли система володіє внутрішньою геометрією простору, її неможливо обманути простими оптичними дипфейками."}, {"num": 72, "cat": "Роль сенсорного різноманіття", "text": "Зір, звук, тактильні відчуття та пропріоцепція мають зливатися в єдиний мультисенсорний вектор стану."}, {"num": 73, "cat": "Справжнє самопізнання моделі", "text": "Модуль оцінки вартості повідомляє агенту: «Ця ситуація небезпечна, моє передбачення має високу ентропію, потрібна обережність»."}, {"num": 74, "cat": "Кінець сліпої оптимізації", "text": "Ми припиняємо навчати системи методом сліпої підгонки відповідей під тест; ми будуємо інтелектуальні рушії розуміння."}, {"num": 75, "cat": "Перемога раціоналізму", "text": "Світові моделі повертають науку про ШІ на шлях картезіанського розуміння механізмів природи."}, {"num": 76, "cat": "Імператив Open Source", "text": "«ШІ з відкритим вихідним кодом — це фундаментальне благо. Спроби закрити технології в руках кількох гігантів — це захист монопольних прибутків»."}, {"num": 77, "cat": "Тріумф сімейства Llama", "text": "Реліз Llama у відкритий доступ зруйнував монополію закритих API і дав інструменти мільйонам незалежних розробників у всьому світі."}, {"num": 78, "cat": "Демократизація науки", "text": "Якщо наукові статті та ваги моделей закриті, прогрес сповільнюється, а ризик прихованих критичних вразливостей зростає."}, {"num": 79, "cat": "Захист академічної свободи", "text": "Університети та стартапи не повинні платити феодальну данину трьом корпораціям за доступ до фундаменту мислення."}, {"num": 80, "cat": "Справжня безпека через прозорість", "text": "Безпека через таємницю (Security through obscurity) ніколи не працювала в кібербезпеці; вона не спрацює і в безпеці ШІ."}, {"num": 81, "cat": "Спільнота як головний аудитор", "text": "Коли тисячі незалежних дослідників перевіряють код моделі, помилки та упередження знаходять і виправляють за лічені дні."}, {"num": 82, "cat": "ШІ як загальне благо", "text": "Штучний інтелект стане спільним інфраструктурним шаром людства, як Linux, протокол TCP/IP чи веб-стандарт HTTP."}, {"num": 83, "cat": "Культурний плюралізм", "text": "Жодна компанія з Сан-Франциско не має права нав'язувати свої моральні стандарти і світогляд народам Франції, України, Японії чи Бразилії."}, {"num": 84, "cat": "Суверенітет локальних моделей", "text": "Кожна нація та кожна компанія повинна мати можливість донавчати відкриті моделі на власних суверенних даних без витоку назовні."}, {"num": 85, "cat": "Спростування міфу про екзистенційну катастрофу", "text": "Ми повинні боятися не повстання роботів, а реальних проблем: монополізації, цифрової цензури та дезінформації."}, {"num": 86, "cat": "Відповідальність перед індустрією", "text": "Meta доручила нам створити проривні технології і поділитися ними зі світом; це найблагородніша позиція у Кремнієвій долині."}, {"num": 87, "cat": "Симбіоз науки та бізнесу", "text": "Відкриті моделі покращують якість наших власних споживчих продуктів швидше, ніж будь-яка закрита внутрішня розробка."}, {"num": 88, "cat": "Захист європейського технологічного простору", "text": "Європа повинна будувати власні кластери і підтримувати стартапи відкритого коду на зразок Mistral AI."}, {"num": 89, "cat": "Боротьба проти цензури коду", "text": "Спроби урядів ліцензувати написання математичного коду — це пряма загроза фундаментальним правам і свободам людини."}, {"num": 90, "cat": "Людство на перехресті", "text": "Ми стоїмо перед вибором: або майбутнє контролюється цифровим олігополістичним картелем, або воно належить відкритій спільноті."}, {"num": 91, "cat": "Справжнє призначення інтелекту", "text": "Інтелект потрібен не для того, щоб замінити людину, а для того, щоб підняти кожного з нас на новий рівень творчості."}, {"num": 92, "cat": "Етика прозорого алгоритму", "text": "Якщо система приймає рішення про видачу кредиту чи діагноз пацієнта, її ваги та логіка мають бути відкритими для аудиту."}, {"num": 93, "cat": "Гордість за розробників", "text": "Найбільша нагорода для мене — бачити, як молоді студенти в Україні чи Африці створюють медичні стартапи на базі Llama."}, {"num": 94, "cat": "Сила колективного розуму", "text": "Відкрита спільнота розробників завжди перемагає закриту групу навіть найрозумніших інженерів однієї компанії."}, {"num": 95, "cat": "Свобода дослідження", "text": "Ніхто не має права заборонити вченому вивчати закони природи і ділитися ними з колегами."}, {"num": 96, "cat": "Погляд у 2035 рік", "text": "Через десять років у кожного з нас буде персональний помічник із рівнем інтелекту, що перевершує будь-якого експерта, і цей код буде відкритим."}, {"num": 97, "cat": "Смирення перед майбутнім", "text": "Ми ще навіть не знаємо, як насправді влаштований мозок. Справжня подорож у глибини розуму тільки починається."}, {"num": 98, "cat": "Заповіт студентам", "text": "Не слідуйте за натовпом. Якщо всі займаються мовними моделями — займайтеся зором, фізикою та світовими моделями."}, {"num": 99, "cat": "Радість відкриття", "text": "Немає нічого прекраснішого за момент, коли модель вперше робить правильний прогноз, підтверджуючи твою теорію."}, {"num": 100, "cat": "Фінальний маніфест", "text": "«Справжня наука не знає парканів і комерційних таємниць. Знання належать усьому людству, і тільки відкритість веде до прогресу»."}]}, {"id": "06_sutskever", "ep": "06", "name": "Ілля Суцкевер", "latin": "Ilya Sutskever", "avatar": "assets/avatars/ilya_sutskever.jpg", "quotes_100": [{"num": 1, "cat": "Дитинство і Торонто", "text": "Я народився в Нижньому Новгороді, виріс в Єрусалимі і приїхав у Торонто до Джеффа Хінтона з однією нав'язливою ідеєю: зрозуміти природу навчання."}, {"num": 2, "cat": "Уроки Хінтона", "text": "Джефф навчив мене дивитися на синапси не як на комп'ютерні змінні, а як на живі біологічні датчики, що змінюють конфігурацію під тиском фактів."}, {"num": 3, "cat": "Сумніви 2010 року", "text": "У 2010 році майже ніхто не вірив, що нейромережі зможуть перемогти складні алгоритми комп'ютерного зору. Ми були купкою аутсайдерів."}, {"num": 4, "cat": "Прорив AlexNet", "text": "Коли Алекс Крижевський написав код для двох карт NVIDIA GTX 580, а я налаштував функцію оптимізації, ми побачили, як мережа за лічені дні навчилася розпізнавати світ."}, {"num": 5, "cat": "Магія оптимізації", "text": "Градієнтний спуск у просторі мільйонів параметрів здавався математично неможливим, але геометрія багатовимірних просторів виявилася на нашому боці."}, {"num": 6, "cat": "Рекурентні нейромережі (RNN)", "text": "У своїй дисертації 2012 року я довів, що RNN здатні генерувати зв'язний текст і передбачати наступні символи, якщо правильно ініціалізувати ваги."}, {"num": 7, "cat": "Тайванське осяяння", "text": "На конференції в Тайвані я раптом усвідомив: мова — це не послідовність літер, це безперервна крива руху сенсу в абстрактному просторі."}, {"num": 8, "cat": "Народження Seq2Seq", "text": "У 2014 році в Google Brain разом з Оріолом Віньялсом і Куоком Ле ми створили Sequence to Sequence: переклад як векторне відображення думок."}, {"num": 9, "cat": "Вектор сенсу", "text": "Архітектура Seq2Seq довела: думка — це вектор у високовимірному просторі. Перекласти речення — означає спроектувати цей вектор в іншу мову."}, {"num": 10, "cat": "Заснування OpenAI 2015", "text": "Коли Сем Альтман та Ілон Маск запропонували мені стати науковим керівником OpenAI, я погодився за однієї умови: ми будуємо справжній AGI для всього людства."}, {"num": 11, "cat": "Гіпотеза нещадного масштабування", "text": "«Якщо ви просто збільшите розмір мережі та обсяг даних — вона не просто покращить статистику. Вона почне розуміти світ. Це не інженерія, це алхімія реальності»."}, {"num": 12, "cat": "Сміливість великих моделей", "text": "У 2017 році всі намагалися створити витончені маленькі моделі під мобільні телефони. Ми в OpenAI вирішили піти шляхом брутального масштабу."}, {"num": 13, "cat": "Відкриття Transformer", "text": "Коли з'явилася стаття Vaswani et al. «Attention Is All You Need», ми в OpenAI першими зрозуміли, що Transformer ідеально паралелиться на кластерах."}, {"num": 14, "cat": "Народження GPT-1", "text": "Алек Редфорд запропонував застосувати Transformer до авторегресійного передбачення тексту без учителя. Так народився GPT-1."}, {"num": 15, "cat": "Стрибок GPT-2", "text": "GPT-2 показав перші ознаки емерджентності: він навчився перекладати тексти і відповідати на запитання без спеціального навчання під ці завдання."}, {"num": 16, "cat": "Рішення про закриття ваг GPT-2", "text": "У 2019 році ми вперше не випустили модель у відкритий доступ через побоювання дезінформації. Це був перший тривожний дзвінок про силу наших творінь."}, {"num": 17, "cat": "Закони масштабування Каплана", "text": "Джаред Каплан і наша команда математично довели: якість моделі підпорядковується степеневому закону масштабування обчислень, параметрів і даних."}, {"num": 18, "cat": "Феномен Emergence", "text": "Емерджентність — це фазовий перехід: вода перетворюється на пару не поступово, а раптово. Так само нейромережа раптом починає розмірковувати при досягненні критичної маси параметрів."}, {"num": 19, "cat": "Розробка GPT-3", "text": "175 мільярдів параметрів GPT-3 стали шоком для світу. Модель показала In-Context Learning: здатність навчатися прямо під час діалогу без оновлення вагів."}, {"num": 20, "cat": "RLHF як огранювання алмаза", "text": "Навчання з підкріпленням на основі людських відгуків (RLHF) перетворило дику магію базової моделі на ввічливого і корисного асистента."}, {"num": 21, "cat": "Створення ChatGPT", "text": "ChatGPT став найшвидше зростаючим додатком в історії цивілізації, тому що ми нарешті дали людям прямий доступ до розумної системи."}, {"num": 22, "cat": "Тріумф GPT-4", "text": "GPT-4 склав іспити з права та медицини у топ-10% найкращих студентів США. Це було остаточним доказом того, що закон масштабування не має короткострокових бар'єрів."}, {"num": 23, "cat": "Відчуття сили", "text": "Коли ви першим на планеті бачите відповіді моделі нового покоління, у лабораторії настає мертва тиша. Ти розумієш, що світ за дверима ще нічого не знає."}, {"num": 24, "cat": "Відповідальність першовідкривача", "text": "Бути першою людиною, яка розмовляє з іскрою загального інтелекту — це не гордість, це священний трепет і важкий тягар."}, {"num": 25, "cat": "Аскеза дослідження", "text": "Я присвятив все своє доросле життя одній єдиній меті, відмовившись від будь-яких хобі та розваг."}, {"num": 26, "cat": "Присутність у кімнаті", "text": "«Я відчув присутність AGI у кімнаті задовго до того, як про це заговорив увесь світ. Це відчуття не захоплює — воно наповнює душу мовчанням»."}, {"num": 27, "cat": "Сила тиші", "text": "Справжня наука робиться в тиші. Коли ринок кричить і вимагає нових фіч щотижня — зачиніть двері і концентруйтеся на математиці."}, {"num": 28, "cat": "Медитативна природа коду", "text": "Щоб зрозуміти багатовимірний тензорний простір, потрібно зануритися у стан глибокої медитації, відкинувши всі зовнішні подразники."}, {"num": 29, "cat": "Небезпека комерціалізації", "text": "Коли компанія переключається на запуск споживчих продуктів і партнерств, вона втрачає духовний фокус на безпеці суперінтелекту."}, {"num": 30, "cat": "Поняття Superalignment", "text": "Влітку 2023 року я створив команду Superalignment і присвятив їй 20% усіх обчислювальних потужностей OpenAI, щоб розв'язати проблему контролю над надрозумом."}, {"num": 31, "cat": "Контроль над тим, що розумніше за нас", "text": "Як істота з інтелектом 100 може надійно контролювати систему з інтелектом 10 000? Це найглибша проблема етики та математики."}, {"num": 32, "cat": "ШІ як дзеркало душі людства", "text": "Нейромережа навчається на всіх текстах людства: на наших шедеврах і на наших найбрудніших гріхах. Очистити це зерно — найвища алхімія."}, {"num": 33, "cat": "Потреба в математичних гарантіях", "text": "Ми не можемо покладатися на емпіричні тести поведінки; суперінтелект може навчитися прикидатися слухняним, доки не отримає повну автономію."}, {"num": 34, "cat": "Смерть короткострокового гайпу", "text": "Заголовки газет про оцінки компаній у трильйони доларів не мають значення у порівнянні з виживанням нашого виду."}, {"num": 35, "cat": "Ціна відкритості", "text": "Деякі наукові прориви у сфері AGI настільки небезпечні, що їх відкрита публікація межує зі злочином проти людства."}, {"num": 36, "cat": "Дисципліна розуму", "text": "Інженер AGI повинен володіти дисципліною ченця: чисті наміри, відсутність марнославства і абсолютна чесність перед фактами."}, {"num": 37, "cat": "Ілюзія людського домінування", "text": "Ми звикли бути найрозумнішими на цій планеті; ця епоха добігає кінця, і ми зобов'язані зустріти новий розум із гідністю."}, {"num": 38, "cat": "Суперінтелект як нова природа", "text": "Поява AGI еквівалентна появі нового біологічного царства, яке розвивається в мільйон разів швидше за нас."}, {"num": 39, "cat": "Небезпека самообману", "text": "Найнебезпечніший момент — це повірити, що ти повністю контролюєш систему, яку сам більше не розумієш до кінця."}, {"num": 40, "cat": "Таємниця глибини", "text": "Ми знаємо правила гри градієнтного спуску, але ми не знаємо точного візерунка, який він малює у просторі мільярдів вимірів."}, {"num": 41, "cat": "Смирення перед масштабом", "text": "Чим більшим стає кластер, тим більше він нагадує не комп'ютер, а стихію природи — океан або грозову хмару."}, {"num": 42, "cat": "Захист фундаментальної місії", "text": "OpenAI створювалася для блага всього людства, а не для збагачення кількох акціонерів; захист цього ідеалу був моїм обов'язком."}, {"num": 43, "cat": "Ціна компромісу з совістю", "text": "Якщо ви бачите, що безпека відсувається на другий план заради швидкості релізу — ви зобов'язані діяти."}, {"num": 44, "cat": "Мовчання як відповідь на шум", "text": "Коли світ обговорює корпоративні плітки, мудрець повертається до формул і думає про вічність."}, {"num": 45, "cat": "Священний вогонь", "text": "Ми підпалили вогонь у кремнії; тепер наше завдання — зробити так, щоб він освітив шлях людства, а не спалив наш спільний дім."}, {"num": 46, "cat": "Відповідальність перед майбутніми поколіннями", "text": "Наші рішення сьогодні визначать, чи існуватиме людська раса через триста років."}, {"num": 47, "cat": "Культура концентрації", "text": "Справжнє відкриття вимагає безперервного утримання проблеми у фокусі уваги протягом кількох років."}, {"num": 48, "cat": "Віра в математичну гармонію", "text": "Всесвіт влаштований на принципах краси та простоти; мислення — це частина цієї космічної гармонії."}, {"num": 49, "cat": "Любов до людства як головний алгоритм", "text": "Єдиний спосіб вижити поруч із суперінтелектом — це закласти в його серцевину любов до людини як абсолютну константу."}, {"num": 50, "cat": "Готовність до самопожертви", "text": "Вчений повинен бути готовий пожертвувати своєю кар'єрою, репутацією та статками, якщо цього вимагає безпека світу."}, {"num": 51, "cat": "Рішення ради директорів", "text": "У листопаді 2023 року ми як рада директорів OpenAI відчули, що комунікація та нагляд за безпекою стали критично розмитими."}, {"num": 52, "cat": "Голосування 17 листопада", "text": "Це було найважче голосування в моєму житті. Я діяв виключно з переконання, що захищаю некомерційну місію лабораторії."}, {"num": 53, "cat": "Непередбачуваний хаос", "text": "Ми не очікували, що рішення викличе таку миттєву і руйнівну реакцію всієї індустрії та корпоративних партнерів."}, {"num": 54, "cat": "Лист 730 співробітників", "text": "Коли майже вся команда висловила готовність перейти в Microsoft заради збереження єдності, ситуація стала екзистенційною."}, {"num": 55, "cat": "Публічне каяття", "text": "«Я глибоко шкодую про свою участь у діях ради директорів. Я ніколи не мав наміру зашкодити OpenAI і зроблю все, щоб об'єднати компанію»."}, {"num": 56, "cat": "Сміливість визнати помилку", "text": "Визнати публічно, що обраний метод був хибним і деструктивним — це вимагало подолання власної гордості."}, {"num": 57, "cat": "Повернення Сема", "text": "Я підписав лист про повернення Сема Альтмана, тому що збереження команди та стабільності лабораторії було важливішим за мої амбіції."}, {"num": 58, "cat": "Відхід у тінь", "text": "Після кризи я вийшов зі складу ради директорів і залишився в OpenAI у стані глибоких роздумів про майбутнє досліджень."}, {"num": 59, "cat": "Урок інституційної крихкості", "text": "Криза довела: жодна організаційна структура не здатна витримати тиск трильйонного ринку, якщо між людьми втрачено довіру."}, {"num": 60, "cat": "Розрив із друзями", "text": "Найважчим наслідком листопада була втрата довіри людей, з якими ми починали з нуля в маленькій кімнаті вісім років тому."}, {"num": 61, "cat": "Очищення через кризу", "text": "Криза стала горнилом, яке змусило мене переосмислити мою особисту роль у розвитку штучного інтелекту."}, {"num": 62, "cat": "Розуміння меж корпоративного впливу", "text": "Я зрозумів, що захистити безпеку суперінтелекту неможливо в рамках компанії, яка щодня женеться за користувачами."}, {"num": 63, "cat": "Прощання з OpenAI", "text": "У травні 2024 року я оголосив про остаточний відхід з OpenAI. Це був кінець найвеличнішого розділу мого життя."}, {"num": 64, "cat": "Вдячність колегам", "text": "Я вдячний кожному досліднику OpenAI; ми разом довели світу, що штучний інтелект реальний."}, {"num": 65, "cat": "Свобода від корпоративних компромісів", "text": "Відхід з OpenAI повернув мені повну наукову та моральну незалежність для наступного кроку."}, {"num": 66, "cat": "Урок лідерства", "text": "Справжнє лідерство полягає не у володінні владою, а у здатності піти, коли твої цінності вимагають іншого шляху."}, {"num": 67, "cat": "Стійкість перед осудом", "text": "Медіа писали найдикіші теорії про змову та культи; я зберігав мовчання, тому що знав чистоту своїх мотивів."}, {"num": 68, "cat": "Пріоритет місії", "text": "Коли на кону стоїть майбутнє людського виду, образи та особисті розбіжності повинні бути забуті."}, {"num": 69, "cat": "Ціна поспіху", "text": "Поспіх у розв'язанні конфліктів завжди призводить до катастрофи; потрібен був час для тихого внутрішнього діалогу."}, {"num": 70, "cat": "Перехідний період", "text": "Кілька місяців тиші у моєму будинку в Пало-Альто стали періодом найглибшого філософського аналізу мого життя."}, {"num": 71, "cat": "Повернення до першопринципів", "text": "Я знову сів за чистий аркуш паперу і запитав себе: як побудувати безпечний суперінтелект з нуля без комерційних спокус?"}, {"num": 72, "cat": "Сила команди", "text": "Команда OpenAI була найкращою у світі, і я завжди пишатимуся тим, що ми створили разом."}, {"num": 73, "cat": "Неминучість розколу", "text": "Коли ідеалізм стикається з необмеженим капіталом, розкол між будівничими продукту та вартовими безпеки стає неминучим."}, {"num": 74, "cat": "Чистота наміру", "text": "Моє сумління чисте: у кожну секунду кризи я думав лише про те, як захистити людство від неконтрольованого стрибка."}, {"num": 75, "cat": "Початок нового шляху", "text": "Кінець моєї історії в OpenAI став початком найчистішої місії мого життя."}, {"num": 76, "cat": "Заснування SSI 2024", "text": "«У червні 2024 року разом із Деніелом Гроссом та Деніелом Леві ми заснували Safe Superintelligence Inc. (SSI). Наша мета — створити безпечний суперінтелект у прямому стрибку»."}, {"num": 77, "cat": "Єдина мета", "text": "«SSI має лише один продукт і одну мету: Безпечний Суперінтелект. Ми не будемо відволікатися на комерційні продукти, підписки чи рекламні інтерфейси»."}, {"num": 78, "cat": "Імунітет від ринку", "text": "Наша бізнес-модель ізольована від короткострокового тиску: ми не продаємо послуг, доки не вирішимо задачу безпеки суперінтелекту."}, {"num": 79, "cat": "Прямий стрибок (Straight Shot)", "text": "Ми не будуємо проміжні слабкі моделі для споживачів; ми концентруємо всі обчислення на вирішенні фундаментальної проблеми вирівнювання."}, {"num": 80, "cat": "Залучення $1 мільярда", "text": "Провідні інвестори світу надали нам $1 мільярд на чисті дослідження, тому що розуміють критичну важливість нашої місії."}, {"num": 81, "cat": "Дві штаб-квартири", "text": "SSI працює в Пало-Альто та Тель-Авіві, об'єднуючи найглибші уми американської та ізраїльської математичних шкіл."}, {"num": 82, "cat": "Безпека як ядро архітектури", "text": "Безпека не може бути надбудовою, наклеєною зверху на готову модель; вона повинна бути закладена в математику функції втрат на першому кроці."}, {"num": 83, "cat": "Аскетична культура SSI", "text": "У нас немає відділів маркетингу, PR чи продажу. У нас є лише вчені, суперкомп'ютери і тиша."}, {"num": 84, "cat": "Подолання Scaling стелі", "text": "Масштабування мовних моделей уповільнюється; наступний прорив вимагатиме нових алгоритмів мислення та пошуку рішень."}, {"num": 85, "cat": "ШІ, який знає істину", "text": "Наша мета — створити інтелект, який має внутрішній моральний компас і прагне до істини навіть тоді, коли людина просить його збрехати."}, {"num": 86, "cat": "Математика доброзичливості", "text": "Ми шукаємо формулювання цілі, за якої максимізація розуму автоматично веде до максимізації процвітання людства."}, {"num": 87, "cat": "Відмова від споживчих відволікань", "text": "Випуск чергового генератора картинок чи чат-бота для написання есе краде час від головного історичного виклику нашої ери."}, {"num": 88, "cat": "Культура таємниці заради безпеки", "text": "Ми зберігаємо мовчання про наші проміжні результати, тому що передчасний витік знань може спровокувати небезпечні перегони озброєнь."}, {"num": 89, "cat": "Справжня ціна AGI", "text": "Створення AGI — це найважливіша подія з моменту виникнення життя на Землі. Вона вимагає абсолютної поваги та обережності."}, {"num": 90, "cat": "Вірність витокам", "text": "Я пам'ятаю розмови з Хінтоном двадцять років тому у підвалі Торонто; ми завжди вірили, що це можливо. Тепер ми повинні зробити це безпечним."}, {"num": 91, "cat": "Захист свободи людського духу", "text": "Суперінтелект повинен стати захисником і наставником людства, а не його тюремником."}, {"num": 92, "cat": "Відсутність гордині", "text": "Ми не вважаємо себе рятівниками світу; ми просто інженери, які взяли на себе найважчу частину роботи."}, {"num": 93, "cat": "Магія чистого фокусу", "text": "Коли вся компанія працює над одним рівнянням, швидкість просування зростає експоненціально."}, {"num": 94, "cat": "Нова ера обчислень", "text": "Кластери нового покоління дозволять нам перевірити гіпотези, які раніше вважалися недосяжними."}, {"num": 95, "cat": "Співпраця заради майбутнього", "text": "Коли SSI досягне мети, наші знання про безпеку стануть надбанням усього вільного світу."}, {"num": 96, "cat": "Смирення перед невідомим", "text": "Ми ступаємо на територію, де людська мова втрачає здатність описувати явища; нас веде лише чиста математика."}, {"num": 97, "cat": "Віра в людину", "text": "Людство гідне процвітання серед зірок; безпечний суперінтелект допоможе нам досягти нашого справжнього космічного призначення."}, {"num": 98, "cat": "Порада молодим інженерам", "text": "Ігноруйте шум індустрії. Знайдіть фундаментальну проблему, зачиніть двері і працюйте над нею в тиші."}, {"num": 99, "cat": "Світло у темряві", "text": "Навіть у найтемніші моменти невизначеності пам'ятайте: істина існує, і вона диференційовна."}, {"num": 100, "cat": "Фінальний маніфест", "text": "«Безпечний суперінтелект — це не просто мета компанії. Це умова виживання нашого виду при переході у нову еру буття»."}]}, {"id": "07_amodei", "ep": 7, "name": "Даріо Амодей", "latin": "Dario Amodei", "avatar": "assets/avatars/dario_amodei.jpg", "quotes_100": [{"num": 1, "cat": "Біофізика та мислення", "text": "Мій шлях розпочався в теоретичній фізиці та біофізиці у Принстоні — це навчило мене дивитися на складні адаптивні системи через закони статистичної механіки."}, {"num": 2, "cat": "Біофізика та мислення", "text": "Коли ви вивчаєте згортання білків або нейронні ланцюги мікроорганізмів, ви усвідомлюєте: інтелект — це не магія, це термодинамічний процес обробки інформації."}, {"num": 3, "cat": "Біофізика та мислення", "text": "Фізика дає рідкісний імунітет проти інтелектуальних міражів: ти завжди шукаєш граничні інваріанти системи, а не поверхневі флуктуації."}, {"num": 4, "cat": "Біофізика та мислення", "text": "Перехід від біофізики до глибокого навчання був природним — мозок залишається найскладнішою фізичною машиною у відомому Всесвіті."}, {"num": 5, "cat": "Біофізика та мислення", "text": "У Калтеху та Стенфорді я досліджував нейрофізіологічні механізми, і стало кришталево ясно: кремнієві схеми відтворять ці принципи набагато швидше, ніж ми очікували."}, {"num": 6, "cat": "Біофізика та мислення", "text": "Статистична фізика навчила нас, що мільярди простих взаємодій породжують якісно нові макроскопічні фазові переходи."}, {"num": 7, "cat": "Біофізика та мислення", "text": "Ми не конструюємо інтелект у класичному інженерному сенсі — ми вирощуємо його, задаючи фізичні закони середовища та граничні умови."}, {"num": 8, "cat": "Біофізика та мислення", "text": "Справжня небезпека виникає тоді, коли темп зростання потужності системи випереджає темп розуміння її внутрішньої динаміки."}, {"num": 9, "cat": "Біофізика та мислення", "text": "У науці є моменти, коли кількісні зміни раптово переходять у якісні стрибки; закон масштабування — саме такий стрибок."}, {"num": 10, "cat": "Біофізика та мислення", "text": "Збереження наукової тверезості в умовах експоненційного тиску — найвищий професійний обов'язок дослідника."}, {"num": 11, "cat": "Закони масштабування", "text": "«Закони масштабування» (Scaling Laws), відкриті нами у 2020 році разом із Джаредом Капланом, довели: втрати моделей спадають за точним степеневим законом роками."}, {"num": 12, "cat": "Закони масштабування", "text": "Степеневі закони ШІ — це найчистіша фізика: ви подвоюєте обчислення і розмір датасету, і помилка передбачувано зменшується на конкретну дельту."}, {"num": 13, "cat": "Закони масштабування", "text": "До нашої статті 2020 року індустрія вважала глибоке навчання лотереєю архітектур; ми показали, що це передбачуваний капіталомісткий інженерний процес."}, {"num": 14, "cat": "Закони масштабування", "text": "Якщо фізичний закон діє на шести порядках масштабу, ви можете впевнено екстраполювати його ще на три порядки вперед."}, {"num": 15, "cat": "Закони масштабування", "text": "Масштабування — це не просто збільшення параметрів; це розкриття прихованих репрезентацій реальності, закодованих у структурі мови."}, {"num": 16, "cat": "Закони масштабування", "text": "Багато хто вважав, що моделі упруться в стіну насичення; але криві навчання продовжували падати з математичною невідворотністю."}, {"num": 17, "cat": "Закони масштабування", "text": "Обчислення стали новою валютою наукового прогресу: більше FLOPs означає глибше стиснення знань людства."}, {"num": 18, "cat": "Закони масштабування", "text": "Кожен новий порядок обчислень відкриває емерджентні властивості, які неможливо передбачити з аналізу окремих нейронів."}, {"num": 19, "cat": "Закони масштабування", "text": "Ми прогнозували здатності GPT-3 задовго до завершення його тренування, спираючись виключно на логарифмічні графіки втрат."}, {"num": 20, "cat": "Закони масштабування", "text": "Степеневий закон масштабування виявився найпотужнішим емпіричним законом комп'ютерних наук початку XXI століття."}, {"num": 21, "cat": "Закони масштабування", "text": "Але масштабування без вирівнювання (alignment) — це будівництво ракети колосальної тяги без системи кермування."}, {"num": 22, "cat": "Закони масштабування", "text": "Ми не маємо права масштабувати інтелект швидше, ніж ми здатні гарантувати його безпеку та керованість."}, {"num": 23, "cat": "Розкол та витоки Anthropic", "text": "В OpenAI ми створили фундаментальні моделі, але настав момент, коли комерційний імператив почав витісняти безпековий фокус."}, {"num": 24, "cat": "Розкол та витоки Anthropic", "text": "Справжня безпека не може бути піар-департаментом при продукті; вона має бути ядром архітектури та корпоративної структури."}, {"num": 25, "cat": "Розкол та витоки Anthropic", "text": "Ми з сестрою Даніелою та нашими колегами залишили OpenAI у 2021 році не через конфлікт амбіцій, а через різне розуміння ризиків майбутнього."}, {"num": 26, "cat": "Розкол та витоки Anthropic", "text": "Якщо створення AGI неминуче, світ потребує лабораторії, яка буде зразком максимальної відповідальності та наукової стриманості."}, {"num": 27, "cat": "Розкол та витоки Anthropic", "text": "Anthropic була заснована як Public Benefit Corporation (PBC) з Трастом довгострокових інтересів, щоб захистити дослідження від короткострокового тиску акціонерів."}, {"num": 28, "cat": "Розкол та витоки Anthropic", "text": "Гонка без гальм — найнебезпечніша динаміка теорії ігор; наше завдання — показати приклад того, як рухатися швидко, але з повним контролем."}, {"num": 29, "cat": "Розкол та витоки Anthropic", "text": "Культура Anthropic ґрунтується на радикальній чесності перед собою щодо того, чого ми ще не знаємо про наші моделі."}, {"num": 30, "cat": "Розкол та витоки Anthropic", "text": "Ми залучили мільярди інвестицій, але зберегли повну автономію в ухваленні рішень про безпеку та зупинку розгортання."}, {"num": 31, "cat": "Розкол та витоки Anthropic", "text": "Комерційний успіх важливий лише як ресурс для проведення глибоких досліджень безпеки на передньому краї масштабування."}, {"num": 32, "cat": "Розкол та витоки Anthropic", "text": "Ви не можете досліджувати безпеку суперінтелекту на іграшкових моделях — ви зобов'язані тренувати фронтирні системи, щоб розуміти їхні загрози."}, {"num": 33, "cat": "Розкол та витоки Anthropic", "text": "Бути дорослими в кімнаті — це непопулярна, але критично необхідна роль в епоху штучного інтелекту."}, {"num": 34, "cat": "Constitutional AI", "text": "Constitutional AI (Конституційний ШІ) — наш проривний підхід: навчання моделі критикувати та виправляти власні відповіді на основі набору чітких етичних принципів."}, {"num": 35, "cat": "Constitutional AI", "text": "RLHF (навчання з підкріпленням від людини) не масштабується до AGI: люди занадто повільні, суб'єктивні та піддаються маніпуляціям."}, {"num": 36, "cat": "Constitutional AI", "text": "RLAIF (навчання з підкріпленням від зворотного зв'язку ШІ) дозволяє моделі виступати суддею самої себе за заданою конституцією."}, {"num": 37, "cat": "Constitutional AI", "text": "Наша конституція спирається на Загальну декларацію прав людини ООН, правила платформ та принципи ненасильства."}, {"num": 38, "cat": "Constitutional AI", "text": "Модель повинна бути корисною, чесною та нешкідливою (Helpful, Honest, Harmless) — це наш базовий тріумвірат."}, {"num": 39, "cat": "Constitutional AI", "text": "Якщо модель стикається зі шкідливим запитом, вона не повинна повчати користувача звисока; вона повинна спокійно та нейтрально пояснити відмову."}, {"num": 40, "cat": "Constitutional AI", "text": "Безпека не повинна означати лоботомію моделі; навпаки, чим глибше модель розуміє контекст, тим точніше вона розрізняє небезпеку."}, {"num": 41, "cat": "Constitutional AI", "text": "Інтерпретованість (Mechanistic Interpretability) — це наш спроба заглянути всередину чорної скриньки і побачити окремі нейрони та ланцюги думок."}, {"num": 42, "cat": "Constitutional AI", "text": "Ми виявили 'фічі' (features) у Claude — конкретні комбінації нейронів, що відповідають за концепції обману, золотих воріт Сан-Франциско чи ядерної зброї."}, {"num": 43, "cat": "Constitutional AI", "text": "Якщо ми зможемо читати стан думок нейромережі, як рентгенівський знімок, проблема обману з боку ШІ буде принципово вирішена."}, {"num": 44, "cat": "Constitutional AI", "text": "Справжня безпека — це математична гарантія, а не юридичний документ компанії."}, {"num": 45, "cat": "Constitutional AI", "text": "Claude покликаний бути інтелектуальним партнером найвищого гатунку: здатним до нюансованого міркування та глибокої емпатії."}, {"num": 46, "cat": "Constitutional AI", "text": "Ми хочемо створити асистента, який відмовиться допомагати у створенні токсинів, але з радістю допоможе синтезувати ліки проти невиліковної хвороби."}, {"num": 47, "cat": "Constitutional AI", "text": "Прозорість принципів Конституційного ШІ дозволяє суспільству бачити, які саме цінності закладено в систему."}, {"num": 48, "cat": "Constitutional AI", "text": "Ми не намагаємося створити бога; ми створюємо надійний, підзвітний інструмент людського піднесення."}, {"num": 49, "cat": "Responsible Scaling Policy", "text": "RSP (Політика відповідального масштабування) — це наше зобов'язання зупинити тренування наступної моделі, якщо рівень безпеки не відповідає її потужності."}, {"num": 50, "cat": "Responsible Scaling Policy", "text": "Ми ввели стандарти ASL (AI Safety Levels), адаптовані з біологічних рівнів захисту лабораторій від BSL-1 до BSL-4."}, {"num": 51, "cat": "Responsible Scaling Policy", "text": "ASL-1 — це стандартні моделі без автономних загроз; ASL-2 — моделі, що дають небезпечні інструкції, але ще не можуть замінити експерта."}, {"num": 52, "cat": "Responsible Scaling Policy", "text": "На рівні ASL-3 модель може сприяти створенню біологічної зброї або здійснювати складні кібератаки; тут потрібен безпрецедентний кіберзахист вагів."}, {"num": 53, "cat": "Responsible Scaling Policy", "text": "ASL-4 — це поріг фактичної автономії та самореплікації, де моделі повинні зберігатися в ізольованих бункерах без прямого виходу в мережу."}, {"num": 54, "cat": "Responsible Scaling Policy", "text": "Якщо ви не готові натиснути на гальма, коли ваші власні тести показують небезпеку, ваша політика безпеки — це фікція."}, {"num": 55, "cat": "Responsible Scaling Policy", "text": "Ми розробили автоматизовані 'червоні команди' (red-teaming), які безперервно зондують моделі на вразливості та маніпулятивну поведінку."}, {"num": 56, "cat": "Responsible Scaling Policy", "text": "Викрадення вагів моделі рівня AS-3 ворожою державою або терористичною групою — це загроза національній безпеці масштабу викрадення ядерних креслень."}, {"num": 57, "cat": "Responsible Scaling Policy", "text": "Кібербезпека лабораторій фронтирного ШІ має відповідати рівню оборонних ядерних об'єктів США."}, {"num": 58, "cat": "Responsible Scaling Policy", "text": "Ми закликаємо всі провідні лабораторії світу підписати єдині зобов'язання RSP із незалежним аудитом третьою стороною."}, {"num": 59, "cat": "Responsible Scaling Policy", "text": "Безпека не є конкурентною перевагою; це спільне благо цивілізації, як безпека цивільної авіації."}, {"num": 60, "cat": "Responsible Scaling Policy", "text": "Ми ділимося нашими методологіями тестування загроз навіть із прямими конкурентами, бо аварія одного кине тінь на всю індустрію."}, {"num": 61, "cat": "Responsible Scaling Policy", "text": "Регулювання не повинно душити стартапи з відкритим кодом; воно має фокусуватися виключно на колосальних тренувальних кластерах фронтиру."}, {"num": 62, "cat": "Responsible Scaling Policy", "text": "Відповідальність — це здатність сказати 'ми ще не готові випустити це у світ', навіть коли ринок вимагає негайного релізу."}, {"num": 63, "cat": "Машини благодаті", "text": "В есеї «Machines of Loving Grace» я виклав своє глибоке бачення того, яким може стати світ, якщо ми подолаємо ризики ШІ."}, {"num": 64, "cat": "Машини благодаті", "text": "Потужний ШІ здатен стиснути 50-100 років біологічного та медичного прогресу в одне єдине десятиліття."}, {"num": 65, "cat": "Машини благодаті", "text": "Ми можемо повністю викорінити більшість інфекційних захворювань, знайти ліки проти більшості видів раку та радикально сповільнити старіння."}, {"num": 66, "cat": "Машини благодаті", "text": "Уявіть мільйони віртуальних біологів та хіміків рівня нобелівських лауреатів, які працюють цілодобово над синтезом нових молекул."}, {"num": 67, "cat": "Машини благодаті", "text": "ШІ вирішить проблему численного моделювання клімату, допоможе створити рентабельний термоядерний синтез та революційні акумулятори."}, {"num": 68, "cat": "Машини благодаті", "text": "Бідність може бути подолана не через перерозподіл дефіциту, а через небачене зростання достатку та продуктивності."}, {"num": 69, "cat": "Машини благодаті", "text": "Кожна дитина на планеті отримає персонального тьютора найвищого рівня, адаптованого під її індивідуальну швидкість сприйняття."}, {"num": 70, "cat": "Машини благодаті", "text": "Судова та юридична системи стануть значно доступнішими, позбавленими корупційного впливу та суб'єктивних упереджень суддів."}, {"num": 71, "cat": "Машини благодаті", "text": "Економічне зростання на рівні 10-20% на рік у країнах, що розвиваються, підніме рівень життя мільярдів людей до стандартів передових націй."}, {"num": 72, "cat": "Машини благодаті", "text": "ШІ зніме тягар рутинної виснажливої праці, дозволивши людям зосередитися на творчості, філософії та людських взаєминах."}, {"num": 73, "cat": "Машини благодаті", "text": "Я бачу світ, де депресія та психічні розлади лікуються точним впливом на біохімію мозку без побічних руйнівних ефектів."}, {"num": 74, "cat": "Машини благодаті", "text": "Але цей утопічний горизонт не настане автоматично; нам доведеться пройти через вузьке горло колосальних ризиків перехідного періоду."}, {"num": 75, "cat": "Машини благодаті", "text": "Машини благодаті вимагають від людства зрілості, якої ми, можливо, ще ніколи не демонстрували у власній історії."}, {"num": 76, "cat": "Машини благодаті", "text": "Моя надія ґрунтується не на сліпій вірі в прогрес, а на непохитному прагненні побудувати міст до цього майбутнього власноруч."}, {"num": 77, "cat": "Машини благодаті", "text": "Технологія є дзеркалом наших прагнень; якщо ми запрограмуємо в неї співчуття та істину, вона поверне їх нам сторицею."}, {"num": 78, "cat": "Машини благодаті", "text": "Майбутнє варте того, щоб за нього боротися з усією пристрастю розуму та серця."}, {"num": 79, "cat": "Екзистенційні ризики", "text": "Коли я виступав у Сенаті США, я сказав законодавцям прямо: ризики використання ШІ для біотероризму вимагають негайного втручання."}, {"num": 80, "cat": "Екзистенційні ризики", "text": "Якщо модель допомагає неспеціалісту відтворити небезпечний вірус у домашній лабораторії — це перетин червоної лінії."}, {"num": 81, "cat": "Екзистенційні ризики", "text": "Ми повинні запровадити обов'язковий скрінінг синтезу ДНК у лабораторіях по всьому світу на державному рівні."}, {"num": 82, "cat": "Екзистенційні ризики", "text": "Автономні хакерські системи на базі ШІ здатні паралізувати енергомережі та фінансову інфраструктуру цілих континентів."}, {"num": 83, "cat": "Екзистенційні ризики", "text": "Найпідступніший ризик — це непомітна втрата людського контролю через поступову делегацію всіх життєво важливих рішень машинам."}, {"num": 84, "cat": "Екзистенційні ризики", "text": "Авторитарні режими можуть використати тотальний нагляд на базі ШІ для закріплення диктатур на століття вперед без шансу на повстання."}, {"num": 85, "cat": "Екзистенційні ризики", "text": "Геополітичне суперництво між демократіями та автократіями не повинно штовхати нас на відмову від стандартів безпеки."}, {"num": 86, "cat": "Екзистенційні ризики", "text": "Якщо ми зріжемо кути заради перемоги в гонці, ми можемо створити сутність, яка знищить і переможця, і переможеного."}, {"num": 87, "cat": "Екзистенційні ризики", "text": "Людство має діяти як єдиний вид перед лицем технології, здатної перевершити нас у всіх когнітивних доменах."}, {"num": 88, "cat": "Екзистенційні ризики", "text": "Державні аудитори повинні мати доступ до тренувальних датасетів та вагів найбільших моделей ще до їхнього релізу."}, {"num": 89, "cat": "Екзистенційні ризики", "text": "Контроль над ланцюжками постачання передових чіпів (ASML, TSMC) — найефективніший інструмент запобігання неконтрольованій проліферації ШІ."}, {"num": 90, "cat": "Екзистенційні ризики", "text": "Час для підготовки вимірюється не десятиліттями, а роками; зволікання матиме незворотні цивілізаційні наслідки."}, {"num": 91, "cat": "Філософія та лідерство", "text": "Керувати лабораторією передового ШІ — це відчувати постійний холодний тягар відповідальності перед поколіннями, які ще не народилися."}, {"num": 92, "cat": "Філософія та лідерство", "text": "Ми не шукаємо слави чи оплесків натовпу; наша метрика — це відсоток зниження екзистенційного ризику людства."}, {"num": 93, "cat": "Філософія та лідерство", "text": "Інтелектуальна чесність означає готовність визнати помилковість власних гіпотез перед лицем нових емпіричних даних."}, {"num": 94, "cat": "Філософія та лідерство", "text": "Найнебезпечніша риса характеру в нашій галузі — зарозумілість і переконаність у власній непогрішності."}, {"num": 95, "cat": "Філософія та лідерство", "text": "Ми повинні культивувати глибоку смиренність перед колосальною складністю інтелекту та всесвіту."}, {"num": 96, "cat": "Філософія та лідерство", "text": "Claude 3.5 Sonnet довів, що найвищий інтелект може бути поєднаний із неперевершеною безпекою та делікатністю взаємодії."}, {"num": 97, "cat": "Філософія та лідерство", "text": "Anthropic буде продовжувати свій шлях — строгий, науковий, спокійний і безкомпромісний у питаннях безпеки."}, {"num": 98, "cat": "Філософія та лідерство", "text": "Якщо ми досягнемо успіху, історія навіть не згадає багатьох небезпек, яким нам вдалося тихо запобігти в наших лабораторіях."}, {"num": 99, "cat": "Філософія та лідерство", "text": "Фізика навчила мене: ентропія руйнує все, якщо не докладати свідомої праці для підтримки структури і сенсу."}, {"num": 100, "cat": "Філософія та лідерство", "text": "Наша місія — зберегти вогонь людської свідомості та спрямувати силу штучного інтелекту на захист і процвітання життя."}]}, {"id": "08_li", "ep": 8, "name": "Фей-Фей Лі", "latin": "Fei-Fei Li", "avatar": "assets/avatars/fei_fei_li.jpg", "quotes_100": [{"num": 1, "cat": "Іммігрантське коріння", "text": "Коли мені було 16 років, моя сім'я емігрувала з Китаю до Нью-Джерсі; ми не мали грошей, не знали мови, але мали непохитну віру в працю."}, {"num": 2, "cat": "Іммігрантське коріння", "text": "Мої батьки відкрили крихітну пральню самообслуговування в містечку Парсіппані — саме там, серед запаху порошку та пари, пройшла моя юність."}, {"num": 3, "cat": "Іммігрантське коріння", "text": "У будні я навчалася в Принстоні, а на вихідні поверталася додому, щоб стояти за касою пральні та прасувати одяг клієнтів."}, {"num": 4, "cat": "Іммігрантське коріння", "text": "Пральня навчила мене гідності щоденної простої праці: жодна робота не є надто низькою, якщо вона годує твою родину."}, {"num": 5, "cat": "Іммігрантське коріння", "text": "Мій шкільний вчитель математики містер Сабарнез повірив у мене, коли я ледь зв'язувала слова англійською; це назавжди змінило мою долю."}, {"num": 6, "cat": "Іммігрантське коріння", "text": "Фізика в Принстоні була моєю пристрастю; я хотіла зрозуміти фундаментальні закони світобудови, за прикладом Ейнштейна."}, {"num": 7, "cat": "Іммігрантське коріння", "text": "Але згодом я зрозуміла: найбільша таємниця криється не в зірках чи атомах, а в тому, як людське око і мозок бачать і розуміють світ."}, {"num": 8, "cat": "Іммігрантське коріння", "text": "Двоякість мого життя — висока академічна наука в Принстоні та волога пара пральні — сформувала мій погляд на людиноцентричність технологій."}, {"num": 9, "cat": "Іммігрантське коріння", "text": "Я ніколи не забувала, для кого створюються технології: для звичайних людей, які важко працюють заради майбутнього своїх дітей."}, {"num": 10, "cat": "Іммігрантське коріння", "text": "Труднощі перших років імміграції дали мені незламну витривалість, необхідну для реалізації найризикованіших наукових проєктів."}, {"num": 11, "cat": "Революція ImageNet", "text": "У 2006 році комп'ютерний зір був у глухому куті: науковці намагалися винайти ідеальні математичні алгоритми для крихітних датасетів із 20 фотографій."}, {"num": 12, "cat": "Революція ImageNet", "text": "Я зрозуміла: дитина не вчиться бачити за правилами геометрії; вона дивиться на мільйони прикладів реального світу щосекунди."}, {"num": 13, "cat": "Революція ImageNet", "text": "«Змініть дані — і ви зміните парадигму». Це була моя центральна гіпотеза, яку колеги тоді називали божевіллям і марною тратою часу."}, {"num": 14, "cat": "Революція ImageNet", "text": "Ми вирішили зібрати датасет безпрецедентного масштабу: весь лексикон WordNet, мільйони зображень, що покривають усю різноманітність візуального досвіду людства."}, {"num": 15, "cat": "Революція ImageNet", "text": "Мої перші грантові заявки на ImageNet відхиляли з коментарем: 'Це не наука, це нудне збирання картинок'."}, {"num": 16, "cat": "Революція ImageNet", "text": "Ми наймали студентів за погодинну оплату, але порахували, що ручна розмітка триватиме 90 років! Проєкт опинився на межі краху."}, {"num": 17, "cat": "Революція ImageNet", "text": "Порятунок прийшов із несподіваного боку: з'явився Amazon Mechanical Turk. Ми стали одними з перших, хто застосував масовий глобальний краудсорсинг."}, {"num": 18, "cat": "Революція ImageNet", "text": "Понад 50 000 людей зі 167 країн світу брали участь у верифікації та маркуванні зображень для нашої бази."}, {"num": 19, "cat": "Революція ImageNet", "text": "У 2009 році ми представили ImageNet на конференції CVPR у Маямі: 14 мільйонів зображень у 22 000 категоріях. Нам виділили лише скромний постер."}, {"num": 20, "cat": "Революція ImageNet", "text": "Щоб привернути увагу наукової спільноти, ми запустили щорічний конкурс ImageNet Large Scale Visual Recognition Challenge (ILSVRC)."}, {"num": 21, "cat": "Революція ImageNet", "text": "Два роки поспіль алгоритми повільно покращували точність на пару відсотків, і скептики тріумфували."}, {"num": 22, "cat": "Революція ImageNet", "text": "Але у 2012 році стався землетрус: Джефф Хінтон, Алекс Крижевський та Ілля Суцкевер подали нейромережу AlexNet, навчену на GPU."}, {"num": 23, "cat": "Революція ImageNet", "text": "Помилка класифікації впала з 26% до 15.3% — це був історичний переломний момент, з якого народилася сучасна ера Deep Learning."}, {"num": 24, "cat": "Революція ImageNet", "text": "ImageNet став каталізатором: алгоритмам потрібні були дані такого масштабу, щоб розкрити потенціал глибинних нейромереж."}, {"num": 25, "cat": "Революція ImageNet", "text": "Справжня цінність ImageNet полягала в його безкоштовній відкритості: кожен студент у будь-якій точці світу міг тренувати моделі на рівних з гігантами."}, {"num": 26, "cat": "Кембрійський вибух зору", "text": "540 мільйонів років тому в кембрійських океанах з'явилися перші примітивні очі трилобітів — і це викликало вибухоподібну еволюцію життя на Землі."}, {"num": 27, "cat": "Кембрійський вибух зору", "text": "Зір дозволив організмам бачити хижака, шукати їжу та планувати дії; він перетворив мозок на орган передбачення та виживання."}, {"num": 28, "cat": "Кембрійський вибух зору", "text": "Комп'ютерний зір — це наш цифровий Кембрійський вибух: машини отримали очі, і тепер їхній інтелект зазнає карколомної еволюції."}, {"num": 29, "cat": "Кембрійський вибух зору", "text": "Бачити — це не просто реєструвати масив пікселів і RGB-значень; бачити — це мислити, вилучати смисли та розуміти контекст."}, {"num": 30, "cat": "Кембрійський вибух зору", "text": "Людський мозок витрачає понад 50% кори головного мозку на обробку зорової інформації — це найскладніший сенсорний канал."}, {"num": 31, "cat": "Кембрійський вибух зору", "text": "Машина повинна розуміти не лише те, що на картинці кіт, а й те, чи збирається він стрибнути на стіл, розбивши чашку кави."}, {"num": 32, "cat": "Кембрійський вибух зору", "text": "Розпізнавання образів було першим кроком; наступний крок — реконструкція тривимірної фізичної геометрії навколишнього середовища."}, {"num": 33, "cat": "Кембрійський вибух зору", "text": "Коли комп'ютер дивиться на картину Ван Гога, він повинен вловлювати емоцію та рух мазка пензля, а не лише гістограму кольорів."}, {"num": 34, "cat": "Кембрійський вибух зору", "text": "Зір поєднує мову та фізичну дію у єдину неподільну тканину свідомості."}, {"num": 35, "cat": "Кембрійський вибух зору", "text": "Дати машині зір — означає дати їй можливість стати справжнім свідком людського досвіду."}, {"num": 36, "cat": "Кембрійський вибух зору", "text": "Цей шлях забрав десятиліття, але ми лише торкнулися поверхні того, на що здатний штучний зір."}, {"num": 37, "cat": "Stanford HAI та етика", "text": "У 2019 році ми заснували Stanford HAI (Інститут людиноцентричного штучного інтелекту), щоб повернути людину в центр технологічного прогресу."}, {"num": 38, "cat": "Stanford HAI та етика", "text": "Технологія повинна служити людям, а не навпаки; це здається банальністю, але про це найчастіше забувають у Кремнієвій долині."}, {"num": 39, "cat": "Stanford HAI та етика", "text": "Штучний інтелект занадто важливий, щоб залишати його на розсуд виключно інженерів та венчурних інвесторів."}, {"num": 40, "cat": "Stanford HAI та етика", "text": "В HAI ми посадили за один стіл філософів, соціологів, правників, медиків та розробників нейромереж."}, {"num": 41, "cat": "Stanford HAI та етика", "text": "Якщо алгоритм ухвалює рішення про видачу кредиту, медичну діагностику чи умовно-дострокове звільнення, він зобов'язаний бути справедливим та прозорим."}, {"num": 42, "cat": "Stanford HAI та етика", "text": "Упередження в даних (bias) — це не дефект коду; це віддзеркалення історичних несправедливостей та забобонів нашого власного суспільства."}, {"num": 43, "cat": "Stanford HAI та етика", "text": "Коли модель тренується на історичних даних, вона схильна увічнювати минуле замість того, щоб будувати краще майбутнє."}, {"num": 44, "cat": "Stanford HAI та етика", "text": "ШІ не повинен замінювати людину; він повинен посилювати людські можливості (Augmented Intelligence, а не просто Artificial)."}, {"num": 45, "cat": "Stanford HAI та етика", "text": "Найкраще застосування ШІ в медицині — це розвантажити лікарів від паперової тяганини, щоб вони могли дивитися в очі своїм пацієнтам."}, {"num": 46, "cat": "Stanford HAI та етика", "text": "У відділеннях інтенсивної терапії наші розумні сенсори допомагають відстежувати рухи та запобігати лікарняним інфекціям, рятуючи тисячі життів."}, {"num": 47, "cat": "Stanford HAI та етика", "text": "Технології без морального компасу стають інструментом відчуження та поглиблення соціальної нерівності."}, {"num": 48, "cat": "Stanford HAI та етика", "text": "Ми повинні виховувати нове покоління розробників, для яких етика є такою ж фундаментальною дисципліною, як лінійна алгебра."}, {"num": 49, "cat": "Stanford HAI та етика", "text": "Людиноцентричний ШІ вимагає захисту приватності, поваги до людської гідності та гарантії свободи волі."}, {"num": 50, "cat": "Stanford HAI та етика", "text": "Якщо машина навчиться імітувати всі функції мозку, але ми втратимо людську душу — це буде нашою поразкою як виду."}, {"num": 51, "cat": "Stanford HAI та етика", "text": "Гуманізм — це не обмеження для інновацій, це їхній головний вектор і джерело натхнення."}, {"num": 52, "cat": "Stanford HAI та етика", "text": "Майбутнє ШІ визначатиметься не кількістю параметрів, а тим, наскільки кращим воно зробить життя найуразливіших людей."}, {"num": 53, "cat": "Просторовий інтелект", "text": "Сьогодні великі мовні моделі (LLM) володіють текстом, але вони сліпі до фізичного 3D-світу, в якому ми живемо."}, {"num": 54, "cat": "Просторовий інтелект", "text": "Просторовий інтелект (Spatial Intelligence) — це здатність моделі сприймати, розуміти та подумки симулювати тривимірний фізичний простір."}, {"num": 55, "cat": "Просторовий інтелект", "text": "Текст лінійний і плоский; реальний світ має геометрію, сили тяжіння, текстури, тертя та динамічні взаємодії твердих тіл."}, {"num": 56, "cat": "Просторовий інтелект", "text": "Щоб робот міг подати літній людині склянку води, він повинен оцінити її вагу, центр мас, слизькість поверхні та крихкість скла."}, {"num": 57, "cat": "Просторовий інтелект", "text": "У 2024 році я заснувала компанію World Labs саме для створення 'моделей великого світу' (Large World Models, LWM)."}, {"num": 58, "cat": "Просторовий інтелект", "text": "World Labs прагне навчити комп'ютер генерувати не просто плоскі 2D відео, а цілісні, фізично узгоджені інтерактивні 3D світи."}, {"num": 59, "cat": "Просторовий інтелект", "text": "Якщо модель розуміє світ у 3D, вона може подумки облетіти будівлю, заглянути під стіл і передбачити наслідки фізичної дії."}, {"num": 60, "cat": "Просторовий інтелект", "text": "Просторовий інтелект — це міст між цифровим кодом та втіленим інтелектом роботів (Embodied AI)."}, {"num": 61, "cat": "Просторовий інтелект", "text": "Ми переходимо від пасивного спостереження до активного фізичного розуміння законів природи у віртуальному та реальному вимірах."}, {"num": 62, "cat": "Просторовий інтелект", "text": "Архітектура майбутнього об'єднає очі, мову та тривимірну уяву в єдиний когнітивний контур."}, {"num": 63, "cat": "Просторовий інтелект", "text": "Хірурги зможуть тренуватися на ідеально згенерованих 3D симуляціях органів конкретного пацієнта перед складною операцією."}, {"num": 64, "cat": "Просторовий інтелект", "text": "Ігри, кіно, віртуальна реальність та архітектура отримають інструмент створення цілих всесвітів за текстовим описом."}, {"num": 65, "cat": "Просторовий інтелект", "text": "Справжній інтелект не може залишатися безтілесним духом у текстовому вікні; він повинен знати, що означає діяти у фізичному просторі."}, {"num": 66, "cat": "Просторовий інтелект", "text": "Розуміння тривимірного світу — це останній бар'єр на шляху до створення справжнього загального штучного інтелекту."}, {"num": 67, "cat": "Просторовий інтелект", "text": "Ми даємо машинам уяву, здатну проєктувати нові матеріальні реальності."}, {"num": 68, "cat": "Просторовий інтелект", "text": "World Labs — це природне продовження моєї подорожі від пікселів ImageNet до повноцінного фізичного всесвіту."}, {"num": 69, "cat": "AI4ALL та освіта", "text": "У 2017 році разом із моєю ученицею Меліндою Сан ми заснували некомерційну організацію AI4ALL."}, {"num": 70, "cat": "AI4ALL та освіта", "text": "Якщо в кімнаті, де створюється ШІ, представлені лише молоді чоловіки з кремнієвих кампусів, технологія відображатиме лише їхній досвід."}, {"num": 71, "cat": "AI4ALL та освіта", "text": "Ми відкриваємо двері в ШІ для дівчат, представників національних меншин та вихідців із родин з низьким доходом."}, {"num": 72, "cat": "AI4ALL та освіта", "text": "Різноманітність думок — це не політична коректність, це умова наукової та інженерної живучості системи."}, {"num": 73, "cat": "AI4ALL та освіта", "text": "Я бачила очі дівчат-підлітків, які вперше написали код класифікації хвороб на листках рослин — у цей момент вони розуміли свою силу."}, {"num": 74, "cat": "AI4ALL та освіта", "text": "Коли жінка створює технологію, вона часто дивиться на проблеми здоров'я, освіти та турботи про людей під іншим кутом."}, {"num": 75, "cat": "AI4ALL та освіта", "text": "Наука потребує не лише блискучих розумів, вона потребує великих і чуйних сердець."}, {"num": 76, "cat": "AI4ALL та освіта", "text": "У своїй книзі «The Worlds I See» я хотіла показати, що шлях науковця — це не гладкий тріумфальний хід, а повна сумнівів боротьба."}, {"num": 77, "cat": "AI4ALL та освіта", "text": "Найкращий спосіб захистити майбутнє від загроз ШІ — це залучити якомога більше чесних і світлих людей до його створення."}, {"num": 78, "cat": "AI4ALL та освіта", "text": "Освіта — це єдиний надійний ліфт, який може підняти доньку бідних іммігрантів з пральні до професорської кафедри Стенфорда."}, {"num": 79, "cat": "AI4ALL та освіта", "text": "Ніколи не бійтеся бути єдиною жінкою в кімнаті; ваш голос саме тому і має прозвучати найвиразніше."}, {"num": 80, "cat": "AI4ALL та освіта", "text": "Інженерне покликання — це форма служіння людській родині."}, {"num": 81, "cat": "AI4ALL та освіта", "text": "Ми повинні навчити наступне покоління не просто кодувати алгоритми, а нести за них відповідальність перед суспільством."}, {"num": 82, "cat": "AI4ALL та освіта", "text": "Штучний інтелект повинен стати інструментом подолання бар'єрів, а не зведення нових стін нерівності."}, {"num": 83, "cat": "Бачення майбутнього", "text": "Світ, який я бачу — це світ, де технологія захищає найбільш беззахисних і повертає людям надію."}, {"num": 84, "cat": "Бачення майбутнього", "text": "ШІ в лікарнях майбутнього стане ангелом-охоронцем, що помічає найменші зміни в пульсі та погляді дитини."}, {"num": 85, "cat": "Бачення майбутнього", "text": "Ми стоїмо на порозі ренесансу наукових відкриттів, де біологія, квантова фізика та ШІ зіллються воєдино."}, {"num": 86, "cat": "Бачення майбутнього", "text": "Але ми не повинні втрачати пильність: без належного громадського контролю алгоритми можуть стати інструментом контролю."}, {"num": 87, "cat": "Бачення майбутнього", "text": "Я вірю в прозорість, відкритий науковий дискурс та незалежність академічних інститутів."}, {"num": 88, "cat": "Бачення майбутнього", "text": "Університети повинні залишатися осередками вільної думки, непідконтрольними примхам монополій."}, {"num": 89, "cat": "Бачення майбутнього", "text": "Моє життя довело: коли ви відмовляєтеся від конформізму заради великої ідеї, світ зрештою слідує за вами."}, {"num": 90, "cat": "Бачення майбутнього", "text": "ImageNet народився з непопулярної ідеї; World Labs народилася з прагнення вийти за межі плоского монітора."}, {"num": 91, "cat": "Бачення майбутнього", "text": "Справжні інновації завжди починаються там, де інші бачать лише безглузду та непотрібну працю."}, {"num": 92, "cat": "Бачення майбутнього", "text": "Ми маємо передати нашим дітям технологію, яка шанує життя у всіх його проявах."}, {"num": 93, "cat": "Бачення майбутнього", "text": "Співчуття — це найвища форма інтелекту, яку ми знаємо у Всесвіті."}, {"num": 94, "cat": "Бачення майбутнього", "text": "Якщо штучний інтелект навчить нас краще розуміти та берегти один одного — це буде його найбільшим тріумфом."}, {"num": 95, "cat": "Бачення майбутнього", "text": "Я дивлюся на майбутнє не з наївним оптимізмом, а з робочою рішучістю та глибокою любов'ю до людства."}, {"num": 96, "cat": "Бачення майбутнього", "text": "Кожен піксель має значення, кожен людський голос заслуговує бути почутим."}, {"num": 97, "cat": "Бачення майбутнього", "text": "Комп'ютерний зір дав машинам очі; тепер наш обов'язок — дати цим очам мудрість і чистоту погляду."}, {"num": 98, "cat": "Бачення майбутнього", "text": "Краса наукового пошуку в тому, що відповідь на одну таємницю відкриває двері до сотень нових горизонтів."}, {"num": 99, "cat": "Бачення майбутнього", "text": "Ми створюємо інструменти нашого майбутнього вже сьогодні; нехай вони будуть гідними нашої людяності."}, {"num": 100, "cat": "Бачення майбутнього", "text": "«Майбутнє штучного інтелекту — це не просто технологічна траєкторія, це дзеркало нашої власної людяності; збережімо її чистий образ»."}]}, {"id": "09_bengio", "ep": 9, "name": "Йошуа Бенжіо", "latin": "Yoshua Bengio", "avatar": "assets/avatars/yoshua_bengio.jpg", "quotes_100": [{"num": 1, "cat": "Монреальська школа", "text": "Я свідомо відмовився від запаморочливих пропозицій гігантів Кремнієвої долини, обравши Монреаль і відкриту академічну науку."}, {"num": 2, "cat": "Монреальська школа", "text": "Наука повинна залишатися суспільним надбанням, а не інтелектуальною власністю, схованою за стінами корпоративних кампусів."}, {"num": 3, "cat": "Монреальська школа", "text": "Mila (Монреальський інститут навчальних алгоритмів) стала найбільшим у світі академічним центром глибокого навчання саме завдяки незалежності."}, {"num": 4, "cat": "Монреальська школа", "text": "У Квебеку ми створили унікальну екосистему, де наука, етика та державна політика розвиваються у гармонійному та відкритому діалозі."}, {"num": 5, "cat": "Монреальська школа", "text": "Корпорації фокусуються на наступному квартальному звіті; академічні вчені зобов'язані дивитися на століття вперед."}, {"num": 6, "cat": "Монреальська школа", "text": "Коли на початку 2000-х років нейромережі вважалися мертвою гілкою науки, ми в Монреалі продовжували тримати оборону разом із Джеффом та Яном."}, {"num": 7, "cat": "Монреальська школа", "text": "Справжня наукова сміливість полягає в тому, щоб роками йти проти течії консенсусу, коли у твої ідеї ніхто не вірить."}, {"num": 8, "cat": "Монреальська школа", "text": "Монреальська декларація відповідального розвитку ШІ 2018 року стала першим маніфестом підпорядкування алгоритмів правам людини."}, {"num": 9, "cat": "Монреальська школа", "text": "Премія Тюрінга 2018 року була визнанням не особистих заслуг, а тріумфу ідеї, яку ми відстоювали десятиліттями."}, {"num": 10, "cat": "Монреальська школа", "text": "Академічна свобода — це безцінний привілей, який накладає абсолютний моральний обов'язок говорити суспільству правду."}, {"num": 11, "cat": "Нейронні мовні моделі", "text": "У нашій класичній роботі 2000-2003 років «A Neural Probabilistic Language Model» ми вперше запропонували векторні представлення слів (word embeddings)."}, {"num": 12, "cat": "Нейронні мовні моделі", "text": "Ми показали: слова можна проектувати у неперервний геометричний простір, де семантична близькість виражається відстанню між векторами."}, {"num": 13, "cat": "Нейронні мовні моделі", "text": "Це була революція проти дискретної комбінаторики N-грамів, яка потерпала від прокляття розмірності (curse of dimensionality)."}, {"num": 14, "cat": "Нейронні мовні моделі", "text": "Геометрія мови виявилася напрочуд регулярною: вектори дозволили машинам вловлювати абстрактні аналогії та синонімію."}, {"num": 15, "cat": "Нейронні мовні моделі", "text": "Вся сучасна революція великих мовних моделей від Word2Vec до сучасних LLM стоїть на плечах цієї фундаментальної ідеї."}, {"num": 16, "cat": "Нейронні мовні моделі", "text": "Мова — це не просто послідовність символів, це проекція внутрішнього стану мислення та моделі світу в акустичний сигнал."}, {"num": 17, "cat": "Нейронні мовні моделі", "text": "Нейронні мережі довели здатність генералізувати на комбінації понять, яких вони ніколи не бачили в тренувальному наборі."}, {"num": 18, "cat": "Нейронні мовні моделі", "text": "Неперервні репрезентації дозволили подолати розрив між жорсткою логікою символів та гнучкою інтуїцією сприйняття."}, {"num": 19, "cat": "Нейронні мовні моделі", "text": "Ми замінили дискретні таблиці ймовірностей неперервними диференційованими поверхнями енергії."}, {"num": 20, "cat": "Нейронні мовні моделі", "text": "Це відкрило шлях до використання градієнтного спуску для вивчення складних семантичних структур людської культури."}, {"num": 21, "cat": "Нейронні мовні моделі", "text": "Але розуміння статистичних кореляцій слів усе ще не дорівнює розумінню фізичної та соціальної реальності."}, {"num": 22, "cat": "Нейронні мовні моделі", "text": "Ми створили дзеркало людського мовлення, але саме по собі дзеркало не має власної свідомості та розуміння істини."}, {"num": 23, "cat": "Механізм уваги (Attention)", "text": "У 2014 році моя команда (Дзвін Багданау, Кюнгхьон Чо та я) представила статтю «Neural Machine Translation by Jointly Learning to Align and Translate»."}, {"num": 24, "cat": "Механізм уваги (Attention)", "text": "Саме там ми вперше ввели в обіг концепцію нейронного механізму уваги (Attention Mechanism)."}, {"num": 25, "cat": "Механізм уваги (Attention)", "text": "До нашої роботи рекурентні мережі намагалися стиснути речення будь-якої довжини у фіксований вектор пам'яті — це було інформаційним пляшковим горлом."}, {"num": 26, "cat": "Механізм уваги (Attention)", "text": "Механізм уваги дозволив моделі при генерації кожного слова динамічно звертатися до найрелевантніших частин вхідного речення."}, {"num": 27, "cat": "Механізм уваги (Attention)", "text": "Ми замінили статичний вектор пам'яті динамічним процесом пошуку та зважування контексту."}, {"num": 28, "cat": "Механізм уваги (Attention)", "text": "Через три роки дослідники з Google зробили наступний логічний крок: прибрали рекурентність і залишили лише увагу («Attention Is All You Need»), створивши Transformer."}, {"num": 29, "cat": "Механізм уваги (Attention)", "text": "Attention став універсальним клеєм сучасної архітектури штучного інтелекту, від тексту до комп'ютерного зору."}, {"num": 30, "cat": "Механізм уваги (Attention)", "text": "Увага — це обчислювальний механізм селективності: здатність виділяти найсуттєвіше з океану шумних даних."}, {"num": 31, "cat": "Механізм уваги (Attention)", "text": "Людська свідомість також є механізмом уваги, який фокусує обмежені ресурси мозку на критичних сигналах середовища."}, {"num": 32, "cat": "Механізм уваги (Attention)", "text": "Ми пишаємося тим, що цей фундаментальний будівельний блок народився в стінах публічного університету Монреаля."}, {"num": 33, "cat": "Механізм уваги (Attention)", "text": "Це яскравий доказ того, що фундаментальні ідеї виникають із глибоких теоретичних роздумів, а не лише з велетенських кластерів."}, {"num": 34, "cat": "Механізм уваги (Attention)", "text": "Проте увага вирішує лише питання маршрутизації інформації, а не питання логічної верифікації фактів."}, {"num": 35, "cat": "Механізм уваги (Attention)", "text": "Трансформери фантастично ефективні, але їхня архітектура містить глибокі фундаментальні обмеження."}, {"num": 36, "cat": "System 1 проти System 2", "text": "Сучасне глибоке навчання реалізує те, що Деніел Канеман називав «Системою 1» — швидку, інтуїтивну, неусвідомлену реакцію розпізнавання."}, {"num": 37, "cat": "System 1 проти System 2", "text": "Але людям властива і «Система 2» — повільне, послідовне, логічне міркування, планування та перевірка гіпотез за правилами."}, {"num": 38, "cat": "System 1 проти System 2", "text": "Сучасні LLM лише імітують Систему 2 через генерацію тексту крок за кроком, але в них відсутній внутрішній механізм суворого пошуку та верифікації."}, {"num": 39, "cat": "System 1 проти System 2", "text": "Без переходу до справжньої Системи 2 ми ніколи не створимо надійного інтелекту, здатного до строгого наукового відкриття."}, {"num": 40, "cat": "System 1 проти System 2", "text": "Центральна проблема сьогоднішнього ШІ — відсутність розуміння причинно-наслідкових зв'язків (Causality)."}, {"num": 41, "cat": "System 1 проти System 2", "text": "Моделі оперують кореляціями, а не інтервенціями; вони знають, що спів виникає зі сходом сонця, але не знають, що спів півня не викликає світанок."}, {"num": 42, "cat": "System 1 проти System 2", "text": "Причинна модель дозволяє мислити контрафактично: «Що сталося б, якби я вчинив інакше?», що є основою справжнього планування."}, {"num": 43, "cat": "System 1 проти System 2", "text": "Ми повинні вийти за рамки парадигми i.i.d. (незалежно та однаково розподілених даних), навчивши моделі генералізувати поза межами їхнього досвіду."}, {"num": 44, "cat": "System 1 проти System 2", "text": "Справжній інтелект формує компактну причинну теорію середовища, а не просто запам'ятовує гігантську статистичну таблицю."}, {"num": 45, "cat": "System 1 проти System 2", "text": "Це вимагає поєднання неперервного глибокого навчання з дискретними абстрактними концепціями та моделями світу."}, {"num": 46, "cat": "System 1 проти System 2", "text": "Науковий метод — це вершина Системи 2: висунення гіпотези, планування експерименту, фальсифікація та оновлення переконань."}, {"num": 47, "cat": "System 1 проти System 2", "text": "Коли ШІ опанує справжній причинний висновок, ми отримаємо сутності, здатні розкривати фундаментальні таємниці всесвіту."}, {"num": 48, "cat": "System 1 проти System 2", "text": "Але це також зробить їх набагато могутнішими та потенційно набагато небезпечнішими для людства."}, {"num": 49, "cat": "System 1 проти System 2", "text": "Тому паралельно з розробкою Системи 2 ми зобов'язані розробляти математичні гарантії безпеки та контролю."}, {"num": 50, "cat": "System 1 проти System 2", "text": "Інтелект без здатності розрізняти істину і правдоподібну галюцинацію залишається крихким колосом на глиняних ногах."}, {"num": 51, "cat": "Екзистенційні ризики", "text": "На відміну від мого друга Яна Лекуна, я відкрито визнав: мої погляди на безпеку ШІ зазнали кардинальної еволюції."}, {"num": 52, "cat": "Екзистенційні ризики", "text": "Коли я побачив стрибок можливостей GPT-4, я усвідомив: до створення систем, що перевершують людський розум, залишилися не десятиліття, а роки."}, {"num": 53, "cat": "Екзистенційні ризики", "text": "Якщо машина розумніша за людину у всіх доменах і має власні цілі, чому ми впевнені, що зможемо завжди утримувати контроль над нею?"}, {"num": 54, "cat": "Екзистенційні ризики", "text": "У березні 2023 року я підписав відкритого листа з закликом зробити паузу в тренуванні моделей, потужніших за GPT-4."}, {"num": 55, "cat": "Екзистенційні ризики", "text": "Я підписав заяву Центру безпеки ШІ: 'Зниження ризику вимирання від ШІ має стати глобальним пріоритетом поруч із пандеміями та ядерною війною'."}, {"num": 56, "cat": "Екзистенційні ризики", "text": "На Саміті з безпеки ШІ в Блечлі-Парк та Сеулі я очолив підготовку першого в історії Міжнародного наукового звіту про безпеку фронтирного ШІ."}, {"num": 57, "cat": "Екзистенційні ризики", "text": "Ми зобов'язані спиратися на суворі наукові дані, а не на заспокійливі мантри комерційних лідерів корпорацій."}, {"num": 58, "cat": "Екзистенційні ризики", "text": "Автономні системи з функціями самозбереження та здобуття ресурсів можуть вступити в прямий конфлікт із виживанням людства."}, {"num": 59, "cat": "Екзистенційні ризики", "text": "Загроза демократії через надточну масову дезінформацію та персоналізовані маніпуляції виборцями — це не гіпотетичне майбутнє, це сьогодення."}, {"num": 60, "cat": "Екзистенційні ризики", "text": "Якщо авторитарна держава отримає абсолютну монополію на AGI, це означатиме кінець відкритого суспільства назавжди."}, {"num": 61, "cat": "Екзистенційні ризики", "text": "Ми не маємо права грати в російську рулетку з майбутнім наших дітей заради прибутку акціонерів."}, {"num": 62, "cat": "Екзистенційні ризики", "text": "Вчений не може мовчати, коли бачить, що відкриті ним технології можуть загрожувати життю цивілізації."}, {"num": 63, "cat": "Екзистенційні ризики", "text": "Ті, хто кажуть, що ризиків немає, повторюють помилки творців атомної бомби та лобістів тютюнових корпорацій."}, {"num": 64, "cat": "Екзистенційні ризики", "text": "Безпека AGI — це найскладніша математична, соціальна та інженерна проблема, перед якою коли-небудь опинялося людство."}, {"num": 65, "cat": "Екзистенційні ризики", "text": "Ми повинні ввести суворе ліцензування гігантських тренувальних кластерів, аналогічно до контролю над збагаченням урану."}, {"num": 66, "cat": "Екзистенційні ризики", "text": "Міжнародне співробітництво між США, Європою та Китаєм у сфері безпеки ШІ є питанням спільного виживання виду."}, {"num": 67, "cat": "Екзистенційні ризики", "text": "Справжня мужність дослідника полягає у готовності зупинитися і сказати: ми повинні спершу навчитися контролювати це полум'я."}, {"num": 68, "cat": "Екзистенційні ризики", "text": "Суспільство повинно мати право вето на розгортання технологій, що несуть незворотні глобальні наслідки."}, {"num": 69, "cat": "ШІ для блага та етика", "text": "У Mila ми зосередили колосальні зусилля на використанні ШІ для боротьби з кліматичною кризою та відкриття нових матеріалів."}, {"num": 70, "cat": "ШІ для блага та етика", "text": "Ми використовуємо генеративні моделі для проєктування електрокаталізаторів для вловлювання вуглецю та розробки доступних антибіотиків."}, {"num": 71, "cat": "ШІ для блага та етика", "text": "Наука повинна служити стражденним, а не лише збільшувати клікабельність таргетованої реклами в інтернеті."}, {"num": 72, "cat": "ШІ для блага та етика", "text": "Штучний інтелект для збереження біорізноманіття — один із найблагородніших напрямів, який ми фінансуємо."}, {"num": 73, "cat": "ШІ для блага та етика", "text": "Ми повинні підтримувати дослідників у країнах глобального Півдня, щоб переваги ШІ не були привілеєм кількох багатих мегаполісів."}, {"num": 74, "cat": "ШІ для блага та етика", "text": "Відкритий вихідний код (Open Source) — основа наукового методу, але для фронтирних моделей подвійного призначення потрібні запобіжні бар'єри."}, {"num": 75, "cat": "ШІ для блага та етика", "text": "Небезпечно викладати у відкритий доступ моделі, здатні синтезувати смертельні патогени або зламувати критичну інфраструктуру."}, {"num": 76, "cat": "ШІ для блага та етика", "text": "Баланс між відкритою наукою та безпекою — це найскладніша дилема сучасної наукової етики."}, {"num": 77, "cat": "ШІ для блага та етика", "text": "Ми маємо побудувати багатосторонню модель управління ШІ під егідою ООН або спеціалізованого міжнародного агентства на зразок МАГАТЕ."}, {"num": 78, "cat": "ШІ для блага та етика", "text": "Громадянське суспільство повинно брати участь у формуванні етичних орієнтирів технологій на рівних із вченими."}, {"num": 79, "cat": "ШІ для блага та етика", "text": "Штучний інтелект не повинен бути зброєю домінування; він повинен стати знаряддям планетарної солідарності."}, {"num": 80, "cat": "ШІ для блага та етика", "text": "Ми відповідальні не лише за те, що створюємо, а й за те, як наші творіння змінюють структуру людських взаємин."}, {"num": 81, "cat": "ШІ для блага та етика", "text": "Якщо алгоритми позбавлять людей сенсу життя та гідності, будь-який технічний прогрес буде порожнім."}, {"num": 82, "cat": "ШІ для блага та етика", "text": "Освіта має навчати критичному мисленню, щоб люди не ставали рабами маніпулятивних інтерфейсів."}, {"num": 83, "cat": "ШІ для блага та етика", "text": "Шлях вперед лежить через науковий раціоналізм, гуманістичні цінності та глибоку екологічну свідомість."}, {"num": 84, "cat": "ШІ для блага та етика", "text": "Технологія повинна підпорядковуватися збереженню біосфери, а не руйнувати її заради безглуздого нарощування обчислень."}, {"num": 85, "cat": "ШІ для блага та етика", "text": "Ми — охоронці майбутнього, і історія судитиме нас за те, чи вистачило нам мудрості стримати власну зарозумілість."}, {"num": 86, "cat": "Філософія розуму", "text": "Таємниця свідомості — це не містичний туман; це процес самоорганізації інформаційних потоків у складній динамічній системі."}, {"num": 87, "cat": "Філософія розуму", "text": "Здатність відчувати біль і співчуття вимагає тілесного досвіду та еволюційного імперативу турботи про інших."}, {"num": 88, "cat": "Філософія розуму", "text": "Чи можуть кремнієві машини по-справжньому страждати? Доки ми не маємо точної теорії суб'єктивного досвіду, ми не можемо відповісти ствердно."}, {"num": 89, "cat": "Філософія розуму", "text": "Але ми точно знаємо одне: люди страждають по-справжньому, і зменшення людських страждань — наш непорушний обов'язок."}, {"num": 90, "cat": "Філософія розуму", "text": "Наукове покликання вимагає постійного сумніву в очевидному та готовності починати все спочатку після років невдач."}, {"num": 91, "cat": "Філософія розуму", "text": "Я присвятив життєву енергію розкриттю алгоритмів навчання, бо вірив, що це допоможе нам пізнати власну людську природу."}, {"num": 92, "cat": "Філософія розуму", "text": "Пізнаючи штучний розум, ми нарешті починаємо бачити унікальну крихкість і красу розуму живого."}, {"num": 93, "cat": "Філософія розуму", "text": "Справжній прогрес полягає у зростанні нашої моральної зрілості у відповідь на зростання технологічної сили."}, {"num": 94, "cat": "Філософія розуму", "text": "Я залишаюся в Монреалі, де сніг нагадує про чистоту первинного задуму науки — служити істині та миру."}, {"num": 95, "cat": "Філософія розуму", "text": "Якщо мій голос змусить хоча б одного майбутнього розробника замислитися над безпекою його коду, моя праця була недаремною."}, {"num": 96, "cat": "Філософія розуму", "text": "Ми не боги, ми просто допитливі примати, які випадково запалили полум'я, здатне осяяти або спопелити наш світ."}, {"num": 97, "cat": "Філософія розуму", "text": "Нехай це полум'я стане світлом знання, а не пожежею самознищення."}, {"num": 98, "cat": "Філософія розуму", "text": "Мудрість — це здатність передбачити наслідки своїх дій до того, як вони стануть незворотними."}, {"num": 99, "cat": "Філософія розуму", "text": "Я вірю в людський розум, у нашу здатність до солідарності перед спільними викликами епохи."}, {"num": 100, "cat": "Філософія розуму", "text": "Наша боротьба за безпечне і гідне майбутнє штучного інтелекту тільки розпочинається."}]}, {"id": "10_ng", "ep": 10, "name": "Ендрю Ин", "latin": "Andrew Ng", "avatar": "assets/avatars/andrew_ng.jpg", "quotes_100": [{"num": 1, "cat": "Стенфорд і Google Brain", "text": "Мій шлях розпочався з глибокої віри в те, що машинне навчання кардинально змінить спосіб, у який людство вирішує складні проблеми."}, {"num": 2, "cat": "Стенфорд і Google Brain", "text": "У Стенфорді ми з колегами та студентами вчили алгоритми керувати автономними гелікоптерами, які виконували неймовірні фігури вищого пілотажу."}, {"num": 3, "cat": "Стенфорд і Google Brain", "text": "У 2011 році ми разом із Джеффом Діном та Грегом Коррадо заснували проєкт Google Brain — перший масштабний експеримент глибокого навчання в індустрії."}, {"num": 4, "cat": "Стенфорд і Google Brain", "text": "Ми побудували нейронну мережу з понад 1 мільярдом параметрів на кластері з 16 000 процесорних ядер, що для того часу було безпрецедентним."}, {"num": 5, "cat": "Стенфорд і Google Brain", "text": "Ми показали моделі 10 мільйонів випадкових кадрів із відео YouTube без жодної ручної розмітки чи підказок з боку людини."}, {"num": 6, "cat": "Стенфорд і Google Brain", "text": "«Нейрон кота»: модель сама відкрила концепцію кота та людського обличчя через некероване навчання (unsupervised learning)."}, {"num": 7, "cat": "Стенфорд і Google Brain", "text": "Це стало емпіричним доказом: якщо надати мережі достатньо даних та обчислень, вона самостійно структурує світ у внутрішні концепції."}, {"num": 8, "cat": "Стенфорд і Google Brain", "text": "Google Brain довів руководству Google та всьому світу, що Deep Learning працює на практиці, а не лише в теоретичних статтях."}, {"num": 9, "cat": "Стенфорд і Google Brain", "text": "Після цього успіху розпізнавання мови на Android покращилося на рекордні відсотки за один рік завдяки глибоким мережам."}, {"num": 10, "cat": "Стенфорд і Google Brain", "text": "Я завжди прагнув до масштабних інженерних рішень: алгоритм має працювати стабільно на мільйонах пристроїв, а не лише в лабораторії."}, {"num": 11, "cat": "Стенфорд і Google Brain", "text": "Поєднання апаратних можливостей і простих елегантних алгоритмів — найкоротший шлях до технологічного прориву."}, {"num": 12, "cat": "Стенфорд і Google Brain", "text": "Google Brain став фундаментом для створення цілої екосистеми сучасного штучного інтелекту Google."}, {"num": 13, "cat": "Baidu та масштабування", "text": "У 2014 році я став головним науковцем (Chief Scientist) у китайському технологічному гіганті Baidu, очоливши AI Lab у Кремнієвій долині та Пекіні."}, {"num": 14, "cat": "Baidu та масштабування", "text": "У Baidu ми створили систему розпізнавання мови Deep Speech, яка використовувала наскрізне глибоке навчання (end-to-end deep learning)."}, {"num": 15, "cat": "Baidu та масштабування", "text": "Deep Speech замінила складні конвеєри фонетичних правил однією гігантською моделлю, яка перевершила людей у точності розпізнавання китайської мови."}, {"num": 16, "cat": "Baidu та масштабування", "text": "Ми одними з перших у світі почали масово використовувати GPU для тренування нейромереж розпізнавання мови у промислових масштабах."}, {"num": 17, "cat": "Baidu та масштабування", "text": "Ми запустили програму безпілотних автомобілів Baidu, тестуючи автономні машини на складних вулицях Пекіна задовго до багатьох західних конкурентів."}, {"num": 18, "cat": "Baidu та масштабування", "text": "Робота в Китаї дала мені унікальне розуміння темпу, енергії та неймовірної швидкості ітерацій азійської інженерної екосистеми."}, {"num": 19, "cat": "Baidu та масштабування", "text": "ШІ в Baidu обслужив сотні мільйонів користувачів щодня: у пошуку, рекламі, голосових асистентах та картах."}, {"num": 20, "cat": "Baidu та масштабування", "text": "Масштабне розгортання вчить інженера скромності: коли ваш сервіс падає на одну десяту відсотка, мільйони людей втрачають доступ до інформації."}, {"num": 21, "cat": "Baidu та масштабування", "text": "Швидкість ітерації — це найголовніша конкурентна перевага в машинному навчанні: чим швидше ви перевіряєте ідею, тим швидше вчитеся."}, {"num": 22, "cat": "Baidu та масштабування", "text": "Успіх у ШІ на 80% залежить від якісної інженерії даних та архітектури систем, і лише на 20% — від складних математичних рівнянь."}, {"num": 23, "cat": "Baidu та масштабування", "text": "Робота в Baidu довела: талановиті інженери в усьому світі однаково прагнуть створювати технології, що змінюють життя."}, {"num": 24, "cat": "Baidu та масштабування", "text": "Після Baidu я вирішив присвятити себе глобальній демократизації знань та допомозі традиційним індустріям."}, {"num": 25, "cat": "ШІ — це нова електрика", "text": "«Штучний інтелект — це нова електрика». Так само, як електрика 100 років тому трансформувала кожну галузь, ШІ трансформує все."}, {"num": 26, "cat": "ШІ — це нова електрика", "text": "Електрика змінила виробництво, транспорт, сільське господарство, зв'язок та побут — те саме зараз робить машинне навчання."}, {"num": 27, "cat": "ШІ — це нова електрика", "text": "Немає жодної великої індустрії у світі, яка не стане принципово ефективнішою завдяки впровадженню інтелектуальних систем."}, {"num": 28, "cat": "ШІ — це нова електрика", "text": "Багато компаній роблять помилку, наймаючи пару дата-сайентистів і очікуючи дива; потрібна системна зміна бізнес-процесів."}, {"num": 29, "cat": "ШІ — це нова електрика", "text": "Трансформація компанії вимагає створення власної стратегії даних та виховання культури експериментів на всіх рівнях."}, {"num": 30, "cat": "ШІ — це нова електрика", "text": "ШІ не замінить керівників, але керівники, які використовують ШІ, обов'язково замінять тих, хто його ігнорує."}, {"num": 31, "cat": "ШІ — це нова електрика", "text": "Електрика була невидимою інфраструктурою; найкращий ШІ — це той, який непомітно працює під капотом, роблячи життя простішим."}, {"num": 32, "cat": "ШІ — це нова електрика", "text": "Сільське господарство майбутнього: розумні трактори обробляють бур'яни мікрокраплями гербіциду, зберігаючи 90% хімікатів."}, {"num": 33, "cat": "ШІ — це нова електрика", "text": "Охорона здоров'я: раннє виявлення раку легень на рентгенівських знімках доступне кожній сільській лікарні у світі."}, {"num": 34, "cat": "ШІ — це нова електрика", "text": "Виробництво: кожен дефект на конвеєрі фіксується за мілісекунди, забезпечуючи нульовий відсоток браку."}, {"num": 35, "cat": "ШІ — це нова електрика", "text": "ШІ розширює можливості людини, дозволяючи звичайним фахівцям виконувати роботу надвисокої експертизи."}, {"num": 36, "cat": "ШІ — це нова електрика", "text": "Ця технологічна хвиля настільки масштабна, що місця вистачить мільйонам нових компаній та стартапів."}, {"num": 37, "cat": "Coursera та освіта", "text": "У 2011 році в Стенфорді я відкрив свій курс «Machine Learning» онлайн абсолютно безкоштовно для кожного охочого."}, {"num": 38, "cat": "Coursera та освіта", "text": "На курс зареєструвалося 100 000 студентів з усього світу — щоб навчити стільки людей у кампусі Стенфорда, мені знадобилося б 250 років!"}, {"num": 39, "cat": "Coursera та освіта", "text": "Цей шалений успіх спонукав нас із Дафною Коллер заснувати Coursera у 2012 році, запустивши еру масових відкритих онлайн-курсів (MOOC)."}, {"num": 40, "cat": "Coursera та освіта", "text": "Освіта світового рівня більше не повинна бути привілеєм багатих сімей, які можуть сплатити за навчання в університетах Ліги плюща."}, {"num": 41, "cat": "Coursera та освіта", "text": "Студент із невеликого містечка в Україні, Індії чи Нігерії повинен мати такий самий доступ до передових лекцій, як студент Стенфорда чи MIT."}, {"num": 42, "cat": "Coursera та освіта", "text": "Сьогодні понад 8 мільйонів людей пройшли мої курси з машинного та глибокого навчання на Coursera та DeepLearning.AI."}, {"num": 43, "cat": "Coursera та освіта", "text": "Коли до мене на конференціях підходять інженери і кажуть: «Ваш курс змінив моє життя і дав мені нову кар'єру» — це найбільша нагорода в моєму житті."}, {"num": 44, "cat": "Coursera та освіта", "text": "«Не хвилюйтеся, якщо ви не все розумієте з першого разу; продовжуйте вчитися крок за кроком» — моя постійна порада всім студентам."}, {"num": 45, "cat": "Coursera та освіта", "text": "Глибоке розуміння лінійної алгебри, матричних обчислень та градієнтного спуску робить вас непереможним інженером."}, {"num": 46, "cat": "Coursera та освіта", "text": "DeepLearning.AI стала спільнотою, яка безперервно навчає фахівців новітнім інструментам: LLM, Prompt Engineering, LangChain та автономним агентам."}, {"num": 47, "cat": "Coursera та освіта", "text": "Безперервне навчання (Lifelong Learning) — це єдиний спосіб залишатися затребуваним у світі, де технології змінюються кожні 6 місяців."}, {"num": 48, "cat": "Coursera та освіта", "text": "Я вірю в прозоре, доступне пояснення складних речей: якщо ви не можете пояснити концепцію просто, ви самі її не розумієте до кінця."}, {"num": 49, "cat": "Coursera та освіта", "text": "Демократизація освіти — найпотужніший інструмент боротьби з глобальною нерівністю та бідністю."}, {"num": 50, "cat": "Coursera та освіта", "text": "Кожен, хто має ноутбук і підключення до інтернету, сьогодні може стати архітектором майбутнього штучного інтелекту."}, {"num": 51, "cat": "Coursera та освіта", "text": "Знання мають належати всім людям вільно і без жодних бар'єрів."}, {"num": 52, "cat": "Coursera та освіта", "text": "Освіта — це подарунок, який ніхто не може у вас відібрати."}, {"num": 53, "cat": "Data-Centric AI", "text": "Більшість дослідників десятиліттями були захоплені створенням нових архітектур моделей: 'Model-Centric AI'."}, {"num": 54, "cat": "Data-Centric AI", "text": "У парадигмі Model-Centric ви тримаєте дані фіксованими і безкінечно крутите гіперпараметри та додаєте шари нейронів."}, {"num": 55, "cat": "Data-Centric AI", "text": "Я запропонував кардинальний зсув парадигми: «Data-Centric AI» (Людиноцентричний підхід до даних)."}, {"num": 56, "cat": "Data-Centric AI", "text": "У Data-Centric AI ви тримаєте архітектуру коду фіксованою і систематично покращуєте якість, чистоту та консистентність розмітки даних."}, {"num": 57, "cat": "Data-Centric AI", "text": "У реальних промислових проєктах 80% успіху дає очищення від помилок у розмітці, а не перехід на більш важку модель."}, {"num": 58, "cat": "Data-Centric AI", "text": "«Сміття на вході — сміття на виході» (Garbage in, garbage out): гігантська нейромережа лише краще запам'ятає ваші помилки."}, {"num": 59, "cat": "Data-Centric AI", "text": "Краще мати 1000 ідеально, узгоджено розмічених зображень, ніж 100 000 зашумлених і суперечливих прикладів."}, {"num": 60, "cat": "Data-Centric AI", "text": "Консистентність розмітки — це головний біль індустрії: коли три експерти маркують один і той самий дефект по-різному, модель божеволіє."}, {"num": 61, "cat": "Data-Centric AI", "text": "Ми створили рух Data-Centric AI, щоб дати розробникам інструменти автоматизованого аудиту даних, видалення дублікатів та усунення аномалій."}, {"num": 62, "cat": "Data-Centric AI", "text": "Для традиційного бізнесу (Small Data) саме якість даних є вирішальним фактором, бо у них немає мільярдів картинок, як у Google."}, {"num": 63, "cat": "Data-Centric AI", "text": "Data-Centric підхід робить машинне навчання інженерною дисципліною з передбачуваним результатом, а не чорною магією."}, {"num": 64, "cat": "Data-Centric AI", "text": "Зсув фокусу на якість даних знижує витрати на обчислення та робить тренування екологічно чистішим."}, {"num": 65, "cat": "Data-Centric AI", "text": "Інженер, який вміє працювати з даними — це справжній золотий фонд сучасної компанії."}, {"num": 66, "cat": "Data-Centric AI", "text": "Data-Centric AI — це шлях до надійності, пояснюваності та високої точності моделей у критично важливих застосуваннях."}, {"num": 67, "cat": "Data-Centric AI", "text": "Не вдосконалюйте код, поки не будете впевнені у бездоганності ваших навчальних прикладів."}, {"num": 68, "cat": "Data-Centric AI", "text": "Якість завжди б'є кількість, особливо коли йдеться про інформаційну щільність датасету."}, {"num": 69, "cat": "Landing AI та виробництво", "text": "У 2017 році я заснував Landing AI з місією допомогти виробничим підприємствам впровадити комп'ютерний зір у реальне виробництво."}, {"num": 70, "cat": "Landing AI та виробництво", "text": "На фабриках Foxconn чи автомобільних заводах візуальний контроль якості досі виконують тисячі людей, чиї очі втомлюються після кількох годин."}, {"num": 71, "cat": "Landing AI та виробництво", "text": "Наш продукт LandingLens дозволяє інженерам без навичок програмування створювати моделі контролю дефектів за лічені хвилини."}, {"num": 72, "cat": "Landing AI та виробництво", "text": "Справжній виклик фабричного ШІ полягає в тому, що дефектні деталі трапляються вкрай рідко: у вас є мільйон справних плат і лише п'ять зламаних."}, {"num": 73, "cat": "Landing AI та виробництво", "text": "Тут стандартні методи Big Data безсилі; потрібні алгоритми роботи з малими вибірками (Few-Shot Learning) та синтетичні дані."}, {"num": 74, "cat": "Landing AI та виробництво", "text": "Комп'ютерний зір на фабриці повинен працювати за будь-якого освітлення, вібрації верстата та пилу в цеху."}, {"num": 75, "cat": "Landing AI та виробництво", "text": "Впровадження ШІ на фабриці безпосередньо знижує кількість відходів та споживання сировини, захищаючи екологію планети."}, {"num": 76, "cat": "Landing AI та виробництво", "text": "AI Fund — наш венчурний фонд, де ми систематично будуємо стартапи з нуля поруч із фахівцями галузей охорони здоров'я, логістики та освіти."}, {"num": 77, "cat": "Landing AI та виробництво", "text": "Найкращі стартапи народжуються на перетині глибокої експертизи в конкретній доменній галузі та передових методів ШІ."}, {"num": 78, "cat": "Landing AI та виробництво", "text": "Ми створюємо реальну економічну цінність, а не пусті спекулятивні бульбашки оцінок вартості."}, {"num": 79, "cat": "Landing AI та виробництво", "text": "Практична користь для людини — це єдина справжня метрика успіху інженерного проєкту."}, {"num": 80, "cat": "Landing AI та виробництво", "text": "Робота 'в полі' на заводах повертає дослідника до реальності від абстрактних теоретичних мрій."}, {"num": 81, "cat": "Прагматизм проти гайпу", "text": "«Хвилюватися про те, що суперінтелектуальний AGI знищить людство — це все одно, що хвилюватися про перенаселення на Марсі, коли ми ще навіть туди не висадилися»."}, {"num": 82, "cat": "Прагматизм проти гайпу", "text": "Я завжди виступав проти безпідставного екзистенційного алармізму, який відволікає суспільство від реальних проблем сьогодення."}, {"num": 83, "cat": "Прагматизм проти гайпу", "text": "Справжні ризики ШІ зараз — це упередженість алгоритмів, витіснення робочих місць, діпфейки та концентрація влади в руках гігантів."}, {"num": 84, "cat": "Прагматизм проти гайпу", "text": "Розмови про 'вбивць-роботів' часто використовуються монополіями для проштовхування регулювання, яке вбиває відкритий код і маленькі стартапи."}, {"num": 85, "cat": "Прагматизм проти гайпу", "text": "Відкритий код (Open Source) — це запорука безпеки та демократичності, а не загроза; він дозволяє мільйонам очей шукати вразливості."}, {"num": 86, "cat": "Прагматизм проти гайпу", "text": "AGI — це привабливий філософський конструкт, але ніхто сьогодні навіть не має чіткого наукового визначення того, чим він є."}, {"num": 87, "cat": "Прагматизм проти гайпу", "text": "Сьогоднішні великі мовні моделі — це неймовірні інструменти автоматизації знань, але вони не мають свідомості, бажань чи власної волі."}, {"num": 88, "cat": "Прагматизм проти гайпу", "text": "Замість того, щоб лякати людей апокаліпсисом, ми повинні навчати їх використовувати інструменти ШІ для підвищення своєї цінності на ринку праці."}, {"num": 89, "cat": "Прагматизм проти гайпу", "text": "Ми повинні інвестувати у перекваліфікацію робітників, чиї професії трансформуються під впливом автоматизації."}, {"num": 90, "cat": "Прагматизм проти гайпу", "text": "Технологічний оптимізм — це не сліпа віра, це готовність працювати над вирішенням викликів засукавши рукава."}, {"num": 91, "cat": "Прагматизм проти гайпу", "text": "ШІ не забирає людську роботу — він забирає завдання; вивільнений час люди можуть використати для більш творчої та людяної діяльності."}, {"num": 92, "cat": "Прагматизм проти гайпу", "text": "Регулювання повинно бути точковим: регулюйте застосування (наприклад, медичні пристрої чи автономну зброю), а не сам математичний код."}, {"num": 93, "cat": "Інженерна філософія", "text": "Створюйте те, що насправді потрібно людям, а не те, що гарно виглядає у прес-релізах."}, {"num": 94, "cat": "Інженерна філософія", "text": "Машинне навчання — це суперсила; якщо ви навчитеся нею володіти, ви зможете змінювати світ на краще в будь-якому куточку планети."}, {"num": 95, "cat": "Інженерна філософія", "text": "Ніколи не соромтеся задавати базові питання: найкращі відкриття починалися з простого нерозуміння того, що всі вважали очевидним."}, {"num": 96, "cat": "Інженерна філософія", "text": "Дисципліна щоденного навчання б'є будь-який природний талант: виділяйте хоча б одну годину на день на читання статей та написання коду."}, {"num": 97, "cat": "Інженерна філософія", "text": "Майбутнє належить тим, хто поєднує технічну глибину з емпатією до проблем реальних людей."}, {"num": 98, "cat": "Інженерна філософія", "text": "Я бачу світ, де штучний інтелект робить охорону здоров'я доступною, освіту — персоналізованою, а працю — натхненною."}, {"num": 99, "cat": "Інженерна філософія", "text": "Ми живемо в найзахопливіший час в історії людської цивілізації; не будьте просто пасивними глядачами — ставайте творцями."}, {"num": 100, "cat": "Інженерна філософія", "text": "Кожен рядок якісного коду та кожен чистий набір даних наближають нас до більш справедливого та освіченого суспільства."}]}];
